function createEventEmitter() {
  const listenersMap = new Map<string, Array<(...args: any[]) => any>>();

  function on(event: string, listener: (...args: any[]) => any) {
    if (!listenersMap.has(event)) {
      listenersMap.set(event, []);
    }
    listenersMap.get(event)!.push(listener);
    return () => off(event, listener);
  }

  function once(event: string, listener: (...args: any[]) => any) {
    function wrappedListener(...args: any[]) {
      off(event, wrappedListener);
      listener(...args);
    }
    return on(event, wrappedListener);
  }

  function off(event: string, listener?: (...args: any[]) => any) {
    const eventListeners = listenersMap.get(event);
    if (!eventListeners) return;
    if (!listener) {
      listenersMap.delete(event);
    } else {
      const index = eventListeners.indexOf(listener);
      if (index > -1) {
        eventListeners.splice(index, 1);
      }
    }
  }

  function emit(event: string, ...args: any[]) {
    const eventListeners = listenersMap.get(event);
    if (!eventListeners) return [];
    const results: any[] = [];
    for (const listener of eventListeners) {
      results.push(listener(...args));
    }
    return results;
  }

  return {
    on,
    once,
    off,
    emit,
  };
}

export { createEventEmitter };
