import { Map } from "immutable";

interface Policy {
  maxRequests: number;
  windowMs: number;
}

const DEFAULT_POLICY: Policy = {
  maxRequests: 3,
  windowMs: 1000,
};

function createRateLimiter({ maxRequests = DEFAULT_POLICY.maxRequests, windowMs = DEFAULT_POLICY.windowMs } = {}): RateLimiter {
  const rateLimiter: RateLimiter = {
    policy: { maxRequests, windowMs },
    requests: new Map<string, { count: number; lastRequestTime: number }>(),

    check(key: string, nowMs: number): boolean {
      const { maxRequests, windowMs } = rateLimiter.policy;
      const windowStartMs = Math.floor(nowMs / windowMs) * windowMs;
      let entry = rateLimiter.requests.get(key, { count: 0, lastRequestTime: windowStartMs });
      if (nowMs - entry.lastRequestTime >= windowMs) {
        entry = { count: 0, lastRequestTime: windowStartMs };
      }
      if (entry.count < maxRequests) {
        entry.count += 1;
        entry.lastRequestTime = nowMs;
        rateLimiter.requests = rateLimiter.requests.set(key, entry);
        return true;
      }
      return false;
    },

    reset(key: string): void {
      rateLimiter.requests = rateLimiter.requests.remove(key);
    },
  };

  return rateLimiter;
}

export { createRateLimiter };
