import { Map } from "immutable";

const limit = 3;
const windowMs = 1000;

function createRateLimiter(): RateLimiter {
  const state = new Map<string, [number, number]>();

  return {
    allow(key, nowMs) {
      const [windowStart, count] = state.get(key, [nowMs, 0]);
      if (nowMs - windowStart >= windowMs) {
        state.set(key, [nowMs, 0]);
      }
      if (count < limit) {
        state.set(key, [windowStart, count + 1]);
        return true;
      }
      return false;
    },
    remaining(key, nowMs) {
      const [windowStart, count] = state.get(key, [nowMs, 0]);
      if (nowMs - windowStart >= windowMs) {
        return limit;
      }
      return Math.max(0, limit - count);
    },
    reset(key) {
      state.delete(key);
    }
  };
}

interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}
