export function createRateLimiter() {
  const state = new Map<string, { startMs: number; count: number }>();

  function allow(key: string, nowMs: number): boolean {
    let entry = state.get(key);
    const windowSize = 1000;
    const limit = 3;

    if (!entry) {
      entry = { startMs: nowMs, count: 0 };
      state.set(key, entry);
    }

    if (nowMs >= entry.startMs + windowSize) {
      entry.startMs = nowMs;
      entry.count = 0;
    }

    entry.count += 1;

    return entry.count <= limit;
  }

  function reset(key: string): void {
    state.delete(key);
  }

  return { allow, reset };
}
