```typescript
interface Listener {
  callback: Function;
  isOneTime: boolean;
}

function createEventEmitter(): {
  on(event: string, callback: Function): void;
  once(event: string, callback: Function): void;
  off(event: string, callback: Function): void;
  emit(event: string, ...args: any[]): any[];
} {
  const listenersMap = new Map<string, Listener[]>();

  return {
    on(event: string, callback: Function): void {
      if (!listenersMap.has(event)) {
        listenersMap.set(event, []);
      }
      listenersMap.get(event)!.push({ callback, isOneTime: false });
    },
    once(event: string, callback: Function): void {
      if (!listenersMap.has(event)) {
        listenersMap.set(event, []);
      }
      listenersMap.get(event)!.push({ callback, isOneTime: true });
    },
    off(event: string, callback: Function): void {
      const eventListeners = listenersMap.get(event);
      if (eventListeners) {
        const index = eventListeners.findIndex(listener => listener.callback === callback);
        if (index !== -1) {
          eventListeners.splice(index, 1);
        }
      }
    },
    emit(event: string, ...args: any[]): any[] {
      const eventListeners = listenersMap.get(event);
      if (!eventListeners || eventListeners.length === 0) {
        return [];
      }

      const copy = [...eventListeners];
      const results = [];

      for (const listener of copy) {
        const result = listener.callback(...args);
        results.push(result);
        if (listener.isOneTime) {
          const index = eventListeners.indexOf(listener);
          if (index !== -1) {
            eventListeners.splice(index, 1);
          }
        }
      }

      return results;
    }
  };
}
