class EventEmitter {
  private listeners: Map<string, Array<{ listener: Listener, isOnce: boolean }>> = new Map();

  on(event: string, listener: Listener): number {
    const eventListeners = this.listeners.get(event) || [];
    eventListeners.push({ listener, isOnce: false });
    this.listeners.set(event, eventListeners);
    return eventListeners.length;
  }

  once(event: string, listener: Listener): number {
    const eventListeners = this.listeners.get(event) || [];
    eventListeners.push({ listener, isOnce: true });
    this.listeners.set(event, eventListeners);
    return eventListeners.length;
  }

  off(event: string, listener: Listener): boolean {
    const eventListeners = this.listeners.get(event) || [];
    for (let i = 0; i < eventListeners.length; i++) {
      const l = eventListeners[i];
      if (l.listener === listener) {
        eventListeners.splice(i, 1);
        this.listeners.set(event, eventListeners);
        return true;
      }
    }
    return false;
  }

  emit(event: string, payload: unknown): unknown[] {
    const eventListeners = this.listeners.get(event) || [];
    const copy = [...eventListeners];
    const results = [];

    for (const listener of copy) {
      const result = listener.listener(payload);
      results.push(result);
      if (listener.isOnce) {
        const index = eventListeners.indexOf(listener);
        if (index !== -1) {
          eventListeners.splice(index, 1);
        }
      }
    }

    return results;
  }

  listenerCount(event: string): number {
    const eventListeners = this.listeners.get(event) || [];
    return eventListeners.length;
  }
}
