export function createRateLimiter() {
  const state = new Map<string, { start: number; count: number }>();

  return {
    check(key: string, nowMs: number): boolean {
      const entry = state.get(key) || { start: nowMs, count: 1 };
      state.set(key, entry);

      const { start, count } = entry;

      if (nowMs >= start + 1000) {
        state.set(key, { start: nowMs, count: 1 });
        return true;
      }

      if (count < 3) {
        state.set(key, { start, count: count + 1 });
        return true;
      }

      return false;
    },
    reset(key: string): void {
      state.delete(key);
    }
  };
}
