export function createEventEmitter() {
  const events = new Map<string, Array<{ fn: Function; once: boolean }>>();
  function on(eventName, listener) {
    const current = events.get(eventName) || [];
    events.set(eventName, [...current, { fn: listener, once: false }]);
  }
  function once(eventName, listener) {
    const current = events.get(eventName) || [];
    events.set(eventName, [...current, { fn: listener, once: true }]);
  }
  function off(eventName, listener) {
    const current = events.get(eventName) || [];
    const newList = [];
    let found = false;
    for (const item of current) {
      if (item.fn === listener && !found) {
        found = true;
        continue;
      }
      newList.push(item);
    }
    events.set(eventName, newList);
  }
  function emit(eventName, ...args) {
    const current = events.get(eventName) || [];
    const results = [];
    for (const item of current) {
      results.push(item.fn(...args));
    }
    const newListeners = current.filter(item => !item.once);
    events.set(eventName, newListeners);
    return results;
  }
  return { on, once, off, emit };
}
