export function createRateLimiter() {
  const storage = new Map<string, { windowEnd: number; remaining: number }>();

  const allow = (key: string, nowMs: number): boolean => {
    let state = storage.get(key);
    if (!state) {
      state = { windowEnd: nowMs - 1000, remaining: 3 };
      storage.set(key, state);
    }

    const { windowEnd, remaining } = state;

    if (nowMs >= windowEnd) {
      state.windowEnd = nowMs + 1000;
      state.remaining = 3;
      state.remaining--;
      return true;
    } else {
      if (remaining > 0) {
        state.remaining--;
        return true;
      }
      return false;
    }
  };

  const reset = (key: string) => {
    storage.delete(key);
  };

  return { allow, reset };
}
