      return entry ? (nowMs < entry.expiresAt ? entry.value : undefined) : undefined;
    },
    has(key, nowMs) {
      const entry = storage.get(key);
      return entry != null && nowMs < entry.expiresAt;
    },
    delete(key) {
      return storage.delete(key);
    },
    size(nowMs) {
      let count = 0;
      for (const entry of storage.values()) {
        if (nowMs < entry.expiresAt) count++;
      }
      return count;
    },
    clear() {
      storage.clear();
    }
  };
