export function createRateLimiter(): RateLimiter {
  const state = new Map<string, { windowStart: number; count: number }>();

  return {
    allow(key: string, nowMs: number): boolean {
      const keyState = state.get(key);
      let windowStart: number;
      let count: number;

      if (!keyState) {
        windowStart = nowMs;
        count = 0;
      } else {
        windowStart = keyState.windowStart;
        count = keyState.count;

        if (nowMs - windowStart >= 1000) {
          windowStart = nowMs;
          count = 0;
        }
      }

      if (count >= 3) {
        return false;
      }

      state.set(key, { windowStart, count: count + 1 });
      return true;
    },

    remaining(key: string, nowMs: number): number {
      const keyState = state.get(key);
      let windowStart: number;
      let count: number;

      if (!keyState) {
        return 3;
      } else {
        windowStart = keyState.windowStart;
        count = keyState.count;

        if (nowMs - windowStart >= 1000) {
          return 3;
        }

        return Math.max(0, 3 - count);
      }
    },

    reset(key: string): void {
      state.delete(key);
    }
  };
}

interface RateLimiter {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
}
