export function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;
  const windows = new Map<string, { start: number; count: number }>();

  return {
    allow(key: string, nowMs: number): boolean {
      const window = windows.get(key) || { start: nowMs, count: 0 };
      const elapsed = nowMs - window.start;

      if (elapsed >= windowMs) {
        window.start = nowMs;
        window.count = 0;
      }

      if (window.count < limit) {
        window.count++;
        windows.set(key, window);
        return true;
      }

      return false;
    },

    remaining(key: string, nowMs: number): number {
      const window = windows.get(key) || { start: nowMs, count: 0 };
      const elapsed = nowMs - window.start;

      if (elapsed >= windowMs) {
        return limit;
      }

      return Math.max(0, limit - window.count);
    },

    reset(key: string): void {
      windows.delete(key);
    },
  };
}

interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}
