export function createRateLimiter(): RateLimiter {
  const state = new Map<string, { count: number; windowStart: number }>();
  return {
    allow: (key: string, nowMs: number): boolean => {
      const current = state.get(key);
      if (!current) {
        current = {
          count: 0,
          windowStart: nowMs
        };
        state.set(key, current);
      }
      if (current.count >= 3) {
        return false;
      }
      current.count++;
      if (nowMs - current.windowStart >= 1000) {
        current.windowStart = nowMs;
      }
      return true;
    },
    remaining: (key: string, nowMs: number): number => {
      const current = state.get(key);
      if (!current) return 0;
      if (nowMs - current.windowStart >= 1000) {
        return 3;
      }
      return current.count;
    },
    reset: (key: string) => {
      const current = state.get(key);
      if (!current) return;
      current.count = 0;
      current.windowStart = nowMs;
      state.set(key, current);
    }
  };
}

interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}
