    get(key, nowMs) {
      const entry = cache.get(key);
      if (entry) {
        const expiresAt = entry.expiresAt;
        if (nowMs < expiresAt) {
          return entry.value;
        }
      }
      return undefined;
    },
    has(key, nowMs) {
      const entry = cache.get(key);
      if (entry) {
        const expiresAt = entry.expiresAt;
        return nowMs < expiresAt;
      }
      return false;
    },
    delete(key) {
      const entry = cache.get(key);
      if (entry) {
        cache.delete(key);
        return true;
      }
      return false;
