export function createTtlCache(): TtlCache {
  const cache = new Map<string, { value: unknown, expiresAt: number }>();
  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      const expiresAt = nowMs + (ttlMs || 1000);
      if (cache.has(key)) {
        const entry = cache.get(key) as { value: unknown, expiresAt: number };
        entry.value = value;
        entry.expiresAt = expiresAt;
      } else {
        cache.set(key, { value, expiresAt });
      }
    },
    get(key: string, nowMs: number): unknown {
      const entry = cache.get(key);
      if (entry && entry.expiresAt > nowMs) {
        return entry.value;
      }
      return undefined;
    },
    has(key: string, nowMs: number): boolean {
      const entry = cache.get(key);
      return entry && entry.expiresAt > nowMs;
    },
    delete(key: string): boolean {
      const entry = cache.delete(key);
      return entry;
    },
    size(nowMs: number): number {
      let count = 0;
      for (const [key, entry] of cache.entries()) {
        if (entry.expiresAt > nowMs) {
          count++;
        }
      }
      return count;
    },
    clear(): void {
      cache.clear();
    }
  };
}

