export function createEventEmitter() {
    const listeners = new Map<string, Array<(value: any) => void>[]>();

    const emit = (event: string, value: any) => {
        const eventListeners = listeners.get(event) || [];
        const results: any[] = [];
        for (const listener of eventListeners) {
            const result = listener.forEach(fn => results.push(fn(value)));
            if (result !== undefined) results.push(result);
        }
        return results;
    };

    const on = (event: string, listener: (value: any) => void) => {
        const existingListeners = listeners.get(event) || [];
        existingListeners.push(listener);
        listeners.set(event, existingListeners);
    };

    const once = (event: string, listener: (value: any) => void) => {
        const existingListeners = listeners.get(event) || [];
        existingListeners.push((value: any) => {
            const result = listener(value);
            listeners.delete(event);
            return result;
        });
        listeners.set(event, existingListeners);
    };

    const off = (event: string, listener: (value: any) => void) => {
        const existingListeners = listeners.get(event) || [];
        const newListeners = existingListeners.filter(fn => fn !== listener);
        listeners.set(event, newListeners);
    };

    return { emit, on, once, off };
}
