```typescript
type Listener = (payload: unknown) => unknown;

interface EventEmitter {
  private listeners: Record<string, { listeners: Listener[]; once: boolean }>;
  private listenerIds: Record<string, number>;

  on(event: string, listener: Listener): number;
  once(event: string, listener: Listener): number;
  off(event: string, listener: Listener): boolean;
  emit(event: string, payload: unknown): unknown[];
  listenerCount(event: string): number;
}

export function createEventEmitter(): EventEmitter {
  const listeners: Record<string, { listeners: Listener[]; once: boolean }> = {};
  const listenerIds: Record<string, number> = {};
  let nextId = 0;

  const addListener = (event: string, listener: Listener, isOnce: boolean) => {
    if (!listeners[event]) {
      listeners[event] = { listeners: [], once: false };
    }
    const eventListeners = listeners[event];
    const id = nextId++;
    listenerIds[id] = event;
    eventListeners.listeners.push({ listener, once: isOnce });
  };

  const removeListener = (event: string, listener: Listener) => {
    if (!listeners[event]) return false;
    const eventListeners = listeners[event];
    const listenersToRemove = eventListeners.listeners.filter((l) => l.listener === listener);
    if (listenersToRemove.length === 0) return false;

    eventListeners.listeners = eventListeners.listeners.filter((l) => l.listener !== listener);
    return true;
  };

  const emit = (event: string, payload: unknown): unknown[] => {
    if (!listeners[event]) return [];
    const eventListeners = listeners[event];
    const results: unknown[] = [];
    for (const { listener, once } of eventListeners.listeners) {
      const result = listener(payload);
      results.push(result);
      if (once) {
        removeListener(event, listener);
      }
    }
    return results;
  };

  const listenerCount = (event: string): number => {
    return listeners[event]?.listeners.length || 0;
  };

  return {
    on(event: string, listener: Listener): number {
      addListener(event, listener, false);
      return listenerCount(event);
    },
    once(event: string, listener: Listener): number {
      addListener(event, listener, true);
      return listenerCount(event);
    },
    off(event: string, listener: Listener): boolean {
      return removeListener(event, listener);
    },
    emit(event: string, payload: unknown): unknown[] {
      return emit(event, payload);
    },
    listenerCount(event: string): number {
      return listenerCount(event);
    },
  };
}
