export function createRateLimiter() {
    const rateLimiter: Record<string, { lastRequestMs: number; requestCount: number }> = {};

    return {
        rateLimit: (key: string, nowMs: number): boolean => {
            const entry = rateLimiter[key];
            if (!entry) {
                rateLimiter[key] = { lastRequestMs: nowMs, requestCount: 1 };
                return true;
            }

            const elapsedMs = nowMs - entry.lastRequestMs;
            if (elapsedMs >= 1000) {
                rateLimiter[key] = { lastRequestMs: nowMs, requestCount: 1 };
                return true;
            }

            if (entry.requestCount < 3) {
                entry.requestCount++;
                return true;
            }

            return false;
        },
        reset: (key: string) => {
            delete rateLimiter[key];
        },
    };
}
