export class RateLimiter {
  private readonly limit: number;
  private readonly windowMs: number;
  private readonly state: Map<string, { windowStart: number; count: number }>;

  constructor(limit: number, windowMs: number) {
    this.limit = limit;
    this.windowMs = windowMs;
    this.state = new Map();
  }

  allow(key: string, nowMs: number): boolean {
    const entry = this.state.get(key);
    const windowStart = entry?.windowStart ?? nowMs - this.windowMs;
    const windowEnd = Math.min(nowMs, windowStart + this.windowMs);

    if (nowMs - windowStart >= this.windowMs) {
      this.state.set(key, { windowStart: nowMs, count: 1 });
      return true;
    }

    const entryData = this.state.get(key) ?? { windowStart, count: 0 };
    const remaining = this.limit - entryData.count;
    if (remaining > 0) {
      this.state.set(key, { windowStart: entryData.windowStart, count: entryData.count + 1 });
      return true;
    }

    return false;
  }

  remaining(key: string, nowMs: number): number {
    const entry = this.state.get(key);
    const windowStart = entry?.windowStart ?? nowMs - this.windowMs;
    const windowEnd = Math.min(nowMs, windowStart + this.windowMs);

    if (nowMs - windowStart >= this.windowMs) {
      return this.limit;
    }

    const entryData = this.state.get(key) ?? { windowStart, count: 0 };
    return Math.max(0, this.limit - entryData.count);
  }

  reset(key: string): void {
    this.state.delete(key);
  }
}

export function createRateLimiter(): RateLimiter {
  return new RateLimiter(3, 1000);
}
