type RateLimiterOptions = {
  nowMs: number;
  key: string;
  quota: number;
};

export function createRateLimiter(options: RateLimiterOptions): {
  (key: string): RateLimiter;
  reset(key: string): void;
} {
  const _rateLimiter = (key: string) => {
    let _nowMs = options.nowMs;
    let _quota = options.quota;
    let _timeWindowMs = 1000;
    let _state = {};

    const rateLimiter = {
      get(key: string): { [key: string]: number; } {
        const { _state } = rateLimiter;
        const state = _state[key] || { count: 0, lastReset: _nowMs };
        const nowMs = options.nowMs;

        if (nowMs - state.lastReset >= _timeWindowMs) {
          state.count = 0;
          state.lastReset = nowMs;
        }

        if (state.count >= _quota) {
          throw new Error(`Rate limit exceeded for key ${key}`);
        }

        state.count += 1;
        return state;
      },

      reset(key: string): void {
        const { _state } = rateLimiter;
        const state = _state[key];
        if (state) {
          state.count = 0;
          state.lastReset = options.nowMs;
        }
      },
    };

    return rateLimiter;
  };

  return _rateLimiter;
}
