export function createTtlCache(): TtlCache {
  const cache: { [key: string]: unknown } = {};
  const expiresAt = Date.now() + 1000;

  const get = (key: string, nowMs: number): unknown => {
    const cachedValue = cache[key];
    if (!cachedValue) return undefined;
    if (nowMs < expiresAt) return cachedValue;
    delete cache[key];
    return undefined;
  };

  const has = (key: string, nowMs: number): boolean => {
    const cachedValue = cache[key];
    return cachedValue !== undefined;
  };

  const set = (key: string, value: unknown, nowMs: number, ttlMs?: number): void => {
    if (ttlMs === 0) expiresAt = nowMs;
    else expiresAt = nowMs + ttlMs;
    cache[key] = value;
  };

  const delete_ = (key: string): boolean => {
    delete cache[key];
    return cache[key] !== undefined;
  };

  const size = (nowMs: number): number => {
    let count = 0;
    for (const key in cache) {
      if (nowMs < expiresAt) {
        count++;
        continue;
      }
      break;
    }
    return count;
  };

  const clear = () => {
    cache = {};
    expiresAt = Date.now() + 1000;
  };

  return { get, has, set, delete_, size, clear };
}
