export function createEventEmitter() {
  const eventMap = new Map<string, Array<{ fn: Function; once: boolean }>>();

  return {
    on: (event: string, listener: Function) => {
      if (!eventMap.has(event)) {
        eventMap.set(event, []);
      }
      eventMap.get(event)!.push({ fn: listener, once: false });
    },
    once: (event: string, listener: Function) => {
      if (!eventMap.has(event)) {
        eventMap.set(event, []);
      }
      eventMap.get(event)!.push({ fn: listener, once: true });
    },
    off: (event: string, listener: Function) => {
      const listeners = eventMap.get(event) || [];
      for (let i = 0; i < listeners.length; i++) {
        if (listeners[i].fn === listener) {
          listeners.splice(i, 1);
          break;
        }
      }
    },
    emit: (event: string): any[] => {
      const listeners = eventMap.get(event) || [];
      const results = [];
      const toRemove = [];

      for (let i = 0; i < listeners.length; i++) {
        const listener = listeners[i];
        const result = listener.fn();
        results.push(result);
        if (listener.once) {
          toRemove.push(i);
        }
      }

      for (let i = toRemove.length - 1; i >= 0; i--) {
        listeners.splice(toRemove[i], 1);
      }

      return results;
    }
  };
}
