export function createRateLimiter() {
  const state = new Map<string, { windowStart: number; count: number }>();

  return {
    allow: (key: string, nowMs: number): boolean => {
      const entry = state.get(key);
      if (!entry) {
        state.set(key, { windowStart: nowMs, count: 0 });
        return true;
      }

      if (nowMs >= entry.windowStart + 1000) {
        state.set(key, { windowStart: nowMs, count: 0 });
      }

      const newCount = state.get(key).count + 1;
      state.set(key, { windowStart: state.get(key).windowStart, count: newCount });

      return newCount <= 3;
    },
    reset: (key: string) => {
      state.delete(key);
    }
  };
