  return {
    set: (key: string, value: unknown, nowMs: number, ttlMs?: number) => {
      const ttl = ttlMs ?? 1000;
      const expiresAt = ttl === 0 ? nowMs : nowMs + ttl;
      cache.set(key, { value, expiresAt });
    },
    get: (key: string, nowMs: number) => {
      const entry = cache.get(key);
      if (entry && nowMs < entry.expiresAt) {
        return entry.value;
      }
      return undefined;
    },
    has: (key: string, nowMs: number) => {
      const entry = cache.get(key);
      return entry && nowMs < entry.expiresAt;
    },
    delete: (key: string) => {
      return cache.delete(key);
    },
    size: (nowMs: number) => {
      let count = 0;
      for (const [key, entry] of cache) {
        if (nowMs < entry.expiresAt) {
          count++;
        }
      }
      return count;
    },
    clear: () => {
      cache.clear();
    }
  };
