export function createEventEmitter(): EventEmitter {
  const listeners = new Map<string, Array<{ listener: Listener; once: boolean }>>();

  const get = (event: string): Array<{ listener: Listener; once: boolean }> => {
    return listeners.get(event) ?? [];
  };

  const set = (event: string, arr: Array<{ listener: Listener; once: boolean }>): void => {
    if (arr.length > 0) {
      listeners.set(event, arr);
    } else {
      listeners.delete(event);
    }
  };

  return {
    on(event: string, listener: Listener): number {
      const arr = get(event);
      arr.push({ listener, once: false });
      set(event, arr);
      return arr.length;
    },
    once(event: string, listener: Listener): number {
      const arr = get(event);
      arr.push({ listener, once: true });
      set(event, arr);
      return arr.length;
    },
    off(event: string, listener: Listener): boolean {
      const arr = get(event);
      for (let i = 0; i < arr.length; i++) {
        if (arr[i].listener === listener) {
          arr.splice(i, 1);
          set(event, arr);
          return true;
        }
      }
      return false;
    },
    emit(event: string, payload: unknown): unknown[] {
      const arr = get(event);
      const results: unknown[] = [];
      let i = 0;
      while (i < arr.length) {
        const reg = arr[i];
        results.push(reg.listener(payload));
        if (reg.once) {
          arr.splice(i, 1);
        } else {
          i++;
        }
      }
      set(event, arr);
      return results;
    },
    listenerCount(event: string): number {
      return get(event).length;
    },
  };
}

type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}
