interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  reset(key: string): void;
}

/**
 * Creates a rate limiter with a fixed policy of 3 requests per 1000ms per key.
 * Timestamps are provided by the caller via `nowMs` for deterministic testing.
 */
export function createRateLimiter(): RateLimiter {
  const MAX_REQUESTS = 3;
  const WINDOW_MS = 1000;

  // Map each key to its current count and the start timestamp of the current window.
  const store = new Map<string, { count: number; windowStart: number }>();

  const limiter: RateLimiter = {
    allow(key: string, nowMs: number): boolean {
      const record = store.get(key);
      if (!record) {
        // First request for this key.
        store.set(key, { count: 1, windowStart: nowMs });
        return true;
      }

      // If the window has fully elapsed, start a fresh window.
      if (nowMs - record.windowStart >= WINDOW_MS) {
        store.set(key, { count: 1, windowStart: nowMs });
        return true;
      }

      // Within the same window: allow if we haven't exceeded the quota.
      if (record.count < MAX_REQUESTS) {
        record.count++;
        store.set(key, record);
        return true;
      }

      // Quota exhausted for the current window.
      return false;
    },

    reset(key: string): void {
      store.delete(key);
    },
  };

  return limiter;
}
