export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
} {
  const store = new Map<string, { value: unknown; expiresAt: number }>();
  const defaultTtl = 1000;

  const set = (key: string, value: unknown, nowMs: number, ttlMs?: number): void => {
    const ttl = ttlMs ?? defaultTtl;
    const expiresAt = nowMs + ttl;
    store.set(key, { value, expiresAt });
  };

  const get = (key: string, nowMs: number): unknown => {
    const entry = store.get(key);
    if (!entry) {
      return undefined;
    }
    if (nowMs >= entry.expiresAt) {
      store.delete(key);
      return undefined;
    }
    return entry.value;
  };

  const has = (key: string, nowMs: number): boolean => {
    const entry = store.get(key);
    if (!entry) {
      return false;
    }
    if (nowMs >= entry.expiresAt) {
      store.delete(key);
      return false;
    }
    return true;
  };

  const del = (key: string): boolean => store.delete(key);

  const size = (nowMs: number): number => {
    let count = 0;
    for (const entry of store.values()) {
      if (nowMs < entry.expiresAt) {
        count++;
      }
    }
    return count;
  };

  const clear = (): void => {
    store.clear();
  };

  return {
    set,
    get,
    has,
    delete: del,
    size,
    clear,
  };
}
