type Listener<T = any> = (...args: any[]) => T;
type ListenerEntry<T = any> = {
  listener: Listener<T>;
  once: boolean;
};

export function createEventEmitter() {
  const listeners: Record<string, ListenerEntry[]> = {};

  function on<T>(event: string, listener: Listener<T>, once: boolean = false): void {
    if (!listeners[event]) {
      listeners[event] = [];
    }
    listeners[event].push({ listener, once });
  }

  function off(event: string, listener: Listener): void {
    const eventListeners = listeners[event];
    if (!eventListeners) return;

    for (let i = 0; i < eventListeners.length; i++) {
      if (eventListeners[i].listener === listener) {
        eventListeners.splice(i, 1);
        break;
      }
    }
  }

  function emit<T>(event: string, ...args: any[]): T[] {
    const eventListeners = listeners[event];
    if (!eventListeners) return [];

    const results: T[] = [];
    for (let i = 0; i < eventListeners.length; i++) {
      const { listener, once } = eventListeners[i];
      const result = listener(...args);
      results.push(result);

      if (once) {
        eventListeners.splice(i, 1);
        i--;
      }
    }
    return results;
  }

  return {
    on,
    off,
    emit,
  };
}
