export function createRateLimiter() {
  const state: Record<string, { count: number; windowStart: number }> = {};

  return {
    check: (key: string, nowMs: number) => {
      const window = 1000;
      const limit = 3;

      if (!state[key]) {
        state[key] = { count: 0, windowStart: nowMs };
        return true;
      }

      const { count, windowStart } = state[key];
      const elapsed = nowMs - windowStart;

      if (elapsed >= window) {
        state[key] = { count: 1, windowStart: nowMs };
        return true;
      }

      if (count < limit) {
        state[key].count++;
        return true;
      }

      return false;
    },
    reset: (key: string) => {
      delete state[key];
    },
  };
}
