function createEventEmitter<T extends Record<string, any[]>>(): EventEmitter<T> {
    const listeners = new Map<string, { listener: Listener; isOneTime: boolean }[]>();

    return {
        on<K extends keyof T>(event: K, listener: Listener<T[K]>) {
            const eventKey = event as string;
            const eventListeners = listeners.get(eventKey) || [];
            eventListeners.push({ listener, isOneTime: false });
            listeners.set(eventKey, eventListeners);
        },
        once<K extends keyof T>(event: K, listener: OneTimeListener<T[K]>) {
            const eventKey = event as string;
            const eventListeners = listeners.get(eventKey) || [];
            eventListeners.push({ listener, isOneTime: true });
            listeners.set(eventKey, eventListeners);
        },
        off<K extends keyof T>(event: K, listener: Listener<T[K]>) {
            const eventKey = event as string;
            const eventListeners = listeners.get(eventKey) || [];
            listeners.set(eventKey, eventListeners.filter(l => l.listener !== listener));
        },
        emit<K extends keyof T>(event: K, ...args: T[K]): ReturnType<Listener<T[K]>>[] {
            const eventKey = event as string;
            const eventListeners = listeners.get(eventKey) || [];
            const results: unknown[] = [];
            const oneTimeListeners: Listener[] = [];

            for (const { listener, isOneTime } of eventListeners) {
                const result = listener(...args);
                results.push(result);
                if (isOneTime) oneTimeListeners.push(listener);
            }

            listeners.set(eventKey, eventListeners.filter(l => !oneTimeListeners.includes(l.listener)));
            return results as ReturnType<Listener<T[K]>>[];
        }
    };
}
