type Listener<T extends any[]> = (...args: T) => any;
type OneTimeListener<T extends any[]> = (...args: T) => any;

interface EventEmitter {
  on<T extends any[]>(eventName: string, listener: Listener<T>): void;
  once<T extends any[]>(eventName: string, listener: OneTimeListener<T>): void;
  off(eventName: string, listener: Listener<any>): void;
  emit(eventName: string, ...args: any[]): any[];
}

function createEventEmitter(): EventEmitter {
  const listeners: { [eventName: string]: { normal: Listener<any>[]; oneTime: OneTimeListener<any>[] } } = {};

  return {
    on<T extends any[]>(eventName: string, listener: Listener<T>): void {
      if (!listeners[eventName]) {
        listeners[eventName] = { normal: [], oneTime: [] };
      }
      listeners[eventName].normal.push(listener as Listener<any>);
    },
    once<T extends any[]>(eventName: string, listener: OneTimeListener<T>): void {
      if (!listeners[eventName]) {
        listeners[eventName] = { normal: [], oneTime: [] };
      }
      listeners[eventName].oneTime.push(listener as OneTimeListener<any>);
    },
    off(eventName: string, listener: Listener<any>): void {
      if (listeners[eventName]) {
        listeners[eventName].normal = listeners[eventName].normal.filter(l => l !== listener);
        listeners[eventName].oneTime = listeners[eventName].oneTime.filter(l => l !== listener);
      }
    },
    emit(eventName: string, ...args: any[]): any[] {
      const results: any[] = [];
      if (listeners[eventName]) {
        listeners[eventName].normal.forEach(listener => results.push(listener(...args)));
        listeners[eventName].oneTime.forEach(listener => {
          const result = listener(...args);
          results.push(result);
          this.off(eventName, listener as Listener<any>);
        });
      }
      return results;
    }
  };
}
