interface RateLimiter {
  isAllowed(key: string, nowMs: number): boolean;
  reset(key: string): void;
}

function createRateLimiter(): RateLimiter {
  const policy = {
    requestsPerWindow: 3,
    windowMs: 1000,
  };

  const state: { [key: string]: { requests: number; lastReset: number } } = {};

  function isAllowed(key: string, nowMs: number): boolean {
    if (!state[key]) {
      state[key] = { requests: 0, lastReset: nowMs };
    }

    const { requests, lastReset } = state[key];
    if (nowMs - lastReset >= policy.windowMs) {
      state[key] = { requests: 1, lastReset: nowMs };
      return true;
    }

    if (requests < policy.requestsPerWindow) {
      state[key] = { requests: requests + 1, lastReset };
      return true;
    }

    return false;
  }

  function reset(key: string): void {
    if (state[key]) {
      delete state[key];
    }
  }

  return { isAllowed, reset };
}
