export function createTtlCache(): TtlCache {
  const cache: Map<string, { value: unknown; expiresAt: number }> = new Map();

  const ttlMs = 1000;

  function set(key: string, value: unknown, nowMs: number, ttlMs: number = ttlMs): void {
    const expiresAt = nowMs + ttlMs;
    cache.set(key, { value, expiresAt });
  }

  function get(key: string, nowMs: number): unknown {
    const entry = cache.get(key);
    if (entry && nowMs < entry.expiresAt) {
      return entry.value;
    }
    return undefined;
  }

  function has(key: string, nowMs: number): boolean {
    const entry = cache.get(key);
    return entry !== undefined && nowMs < entry.expiresAt;
  }

  function delete(key: string): boolean {
    return cache.delete(key);
  }

  function size(nowMs: number): number {
    let count = 0;
    for (const entry of cache.values()) {
      if (nowMs < entry.expiresAt) {
        count++;
      }
    }
    return count;
  }

  function clear(): void {
    cache.clear();
  }

  return {
    set,
    get,
    has,
    delete,
    size,
    clear,
  };
}
