import { EventEmitter } from 'events';

export function createEventEmitter() {
    let ee = new EventEmitter();
    let registry = new Map();

    function listenerWrapper(listener) {
        return function (...args) {
            let result = listener(...args);
            if (listener.isOnce) {
                ee.removeListener(listener.getName(), listener.getCallback());
            }
            return Promise.resolve(result);
        };
    }

    function addListener(eventName, listener) {
        if (!registry.has(eventName)) {
            registry.set(eventName, []);
        }
        if (!listener.isOnce && ee.listenerCount(eventName) > 0) {
            ee.on(eventName, listenerWrapper(listener));
        } else {
            ee.removeListener(eventName, listenerWrapper(listener));
        }
        registry.get(eventName).push(listener);
        return listener;
    }

    function removeListener(eventName, listener) {
        let eventListeners = registry.get(eventName);
        if (!eventListeners) return;
        let index = eventListeners.indexOf(listener);
        if (index > -1) {
            eventListeners.splice(index, 1);
        }
    }

    function emit(eventName, ...args) {
        let eventListeners = registry.get(eventName) || [];
        let results = [];

        eventListeners.forEach(listener => {
            results.push(listener(...args));
        });

        return Promise.all(results);
    }

    function createListener(eventName, callback, isOnce) {
        return {
            getName: () => eventName,
            isOnce: !!isOnce,
            getCallback: () => callback,
        };
    }

    return {
        on(eventName, callback) {
            addListener(eventName, createListener(eventName, callback, false));
        },
        once(eventName, callback) {
            addListener(eventName, createListener(eventName, callback, true));
        },
        off(eventName, callback) {
            removeListener(eventName, createListener(eventName, callback, false));
            ee.removeListener(eventName, listenerWrapper(callback));
        },
        emit(eventName, ...args) {
            return emit(eventName, ...args);
        },
    };
}
