import { EventEmitter as NodeEventEmitter } from 'events'

export function createEventEmitter(): EventEmitter {
  const ee = new NodeEventEmitter()
  return ({
    on(event, listener) {
      ee.on(event, listener)
      return ee.listenerCount(event)
    },
    once(event, listener) {
      ee.once(event, listener)
      return ee.listenerCount(event)
    },
    off(event, listener) {
      const removed = ee.removeListener(event, listener)
      return removed
    },
    emit(event, payload) {
      const listeners = ee.listeners(event).slice()
      const results = listeners.map(listener => listener(payload))
      ee.emit(event, payload) // ensures once listeners are removed
      return results
    },
    listenerCount(event) {
      return ee.listenerCount(event)
    },
  }) as EventEmitter
}

