import { Map } from "immutable";

type Timestamp = number;

function createRateLimiter() {
  let timeWindows = new Map<string, Timestamp>();

  function isRequestAllowed(key: string, nowMs: Timestamp): boolean {
    const windowStart = timeWindows.get(key, 0);
    if (nowMs - windowStart >= 1000) {
      timeWindows = timeWindows.set(key, nowMs);
      return true;
    }
    const requestsLeft = 3 - (nowMs - windowStart) % 1000;
    if (requestsLeft > 0) {
      return true;
    }
    return false;
  }

  function recordRequest(key: string, nowMs: Timestamp) {
    if (!isRequestAllowed(key, nowMs)) {
      throw new Error("Request rate exceeded");
    }
    timeWindows = timeWindows.set(key, nowMs - (nowMs % 1000));
  }

  function reset(key: string) {
    timeWindows = timeWindows.delete(key);
  }

  return {
    recordRequest,
    reset,
  };
}
