export function createTodoApp() {
  let todosById = new Map<number, { id: number; text: string; completed: boolean }>();
  let nextId = 1;

  function addTodo(text: string): { id: number; text: string; completed: boolean } {
    const newTodo = { id: nextId, text, completed: false };
    todosById.set(nextId, newTodo);
    nextId++;
    return newTodo;
  }

  function getTodo(id: number): { id: number; text: string; completed: boolean } | undefined {
    return todosById.get(id);
  }

  function toggleTodo(id: number): void {
    const todo = getTodo(id);
    if (todo) {
      const updatedTodo = { ...todo, completed: !todo.completed };
      todosById.set(id, updatedTodo);
    }
  }

  function deleteTodo(id: number): boolean {
    if (todosById.has(id)) {
      todosById.delete(id);
      return true;
    }
    return false;
  }

  function listTodos(): Array<{ id: number; text: string; completed: boolean }> {
    return Array.from(todosById.values());
  }

  function listCompleted(): Array<{ id: number; text: string; completed: boolean }> {
    return Array.from(todosById.values()).filter(todo => todo.completed);
  }

  function listPending(): Array<{ id: number; text: string; completed: boolean }> {
    return Array.from(todosById.values()).filter(todo => !todo.completed);
  }

  function clearCompleted(): void {
    const pendingTodos = listPending();
    todosById.clear();
    pendingTodos.forEach(todo => addTodo(todo.text));
  }

  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
    clearCompleted,
  };
