import { LRUCache } from 'lru-cache';

export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
} {
  const cache = new LRUCache<string, { value: unknown; expires: number }>({
    max: 1000,
    ttl: 1000,
    ttlMillis: true,
    dispose: (key, value) => { /* unused */ },
    maxAge: 1000,
  });

  return {
    set(key, value, now, ttl = 1000) {
      const expiresAtMs = now + ttl;
      cache.set(key, { value, expires: expiresAtMs });
    },
    get(key, now) {
      const item = cache.get(key);
      if (!item || now >= item.expires) return undefined;
      return item.value;
    },
    has(key, now) {
      const item = cache.get(key);
      return Boolean(item && now < item.expires);
    },
    delete(key) {
      return cache.delete(key);
    },
    size(now) {
      return cache.keys().filter(key => now < cache.get(key).expires).length;
    },
    clear() {
      cache.reset();
    },
  };
}
