import { Map } from "immutable";

export function createTtlCache(): TtlCache {
  const cache = new Map<string, CacheEntry>();

  return {
    set: (key, value, nowMs, ttlMs = 0) => {
      const expiresAt = ttlMs === 0 ? nowMs : nowMs + ttlMs;
      cache.set(key, { value, expiresAt });
    },
    get: (key, nowMs) => {
      const entry = cache.get(key);
      if (entry && nowMs < entry.expiresAt) {
        return entry.value;
      }
      return undefined;
    },
    has: (key, nowMs) => {
      const entry = cache.get(key);
      return entry && nowMs < entry.expiresAt;
    },
    delete: (key) => {
      if (cache.has(key)) {
        cache.delete(key);
        return true;
      }
      return false;
    },
    size: (nowMs) => {
      return cache.filter(entry => nowMs < entry.expiresAt).count();
    },
    clear: () => {
      cache.clear();
    }
  };
}

interface CacheEntry {
  value: unknown;
  expiresAt: number;
}

interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
}
