export function createEventEmitter() {
  const events = new Map<string, Array<{ listener: Function; once: boolean }>>();

  return {
    on(event: string, listener: Function, once = false): void {
      if (!events.has(event)) {
        events.set(event, []);
      }
      events.get(event)!.push({ listener, once });
    },
    off(event: string, listener: Function): void {
      const listeners = events.get(event);
      if (!listeners) return;
      for (let i = 0; i < listeners.length; i++) {
        if (listeners[i].listener === listener) {
          listeners.splice(i, 1);
          return;
        }
      }
    },
    emit(event: string, ...args: any[]): any[] {
      const listeners = events.get(event);
      if (!listeners) return [];
      const results = [];
      for (let i = 0; i < listeners.length; i++) {
        const listenerInfo = listeners[i];
        const result = listenerInfo.listener(...args);
        results.push(result);
        if (listenerInfo.once) {
          listeners.splice(i, 1);
          i--;
        }
      }
      return results;
    }
  };
}
