export function createRateLimiter(): RateLimiter {
  const map = new Map<string, { windowStart: number; remaining: number }>();
  const limit = 3;
  const windowMs = 1000;

  return {
    allow(key: string, nowMs: number): boolean {
      let state = map.get(key);
      if (!state) {
        const windowStart = Math.floor(nowMs / windowMs) * windowMs;
        state = { windowStart, remaining: limit };
        map.set(key, state);
        return true;
      }

      const { windowStart, remaining } = state;
      if (nowMs - windowStart >= windowMs) {
        const newWindowStart = Math.floor(nowMs / windowMs) * windowMs;
        state = { windowStart: newWindowStart, remaining: limit };
        map.set(key, state);
      } else if (remaining <= 0) {
        return false;
      } else {
        state.remaining -= 1;
        map.set(key, state);
      }
      return true;
    },

    remaining(key: string, nowMs: number): number {
      const state = map.get(key);
      if (!state) {
        return 0;
      }
      const { windowStart, remaining } = state;
      if (nowMs - windowStart >= windowMs) {
        return limit;
      }
      return remaining;
    },

    reset(key: string): void {
      map.delete(key);
    },
  };
}

interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}
