export function createEventEmitter() {
  const events = new Map<string, Array<{ func: Function, isOneTime: boolean }>>();

  return {
    on(eventName: string, listener: Function, oneTime?: boolean): void {
      if (!events.has(eventName)) {
        events.set(eventName, []);
      }
      events.get(eventName)!.push({ func: listener, isOneTime: oneTime ?? false });
    },

    off(eventName: string, listener: Function): void {
      if (events.has(eventName)) {
        const listeners = events.get(eventName)!;
        for (let i = 0; i < listeners.length; i++) {
          if (listeners[i].func === listener) {
            listeners.splice(i, 1);
            break;
          }
        }
      }
    },

    emit(eventName: string, ...args: any[]): any[] {
      if (!events.has(eventName)) {
        return [];
      }
      const listeners = events.get(eventName)!;
      const result: any[] = [];
      const toRemove: Array<{ func: Function, isOneTime: boolean }> = [];
      const copy = [...listeners];
      for (const listener of copy) {
        try {
          const returnValue = listener.func(...args);
          result.push(returnValue);
          if (listener.isOneTime) {
            toRemove.push(listener);
          }
        } catch (err) {
          // Handle errors, but per user's request, no error handling mentioned, so we can ignore.
        }
      }
      // Remove the one-time listeners from the original array
      for (const listener of toRemove) {
        const index = listeners.indexOf(listener);
        if (index !== -1) {
          listeners.splice(index, 1);
        }
      }
      return result;
    }
  };
