export function createRateLimiter(): RateLimiter {
  const map = new Map<string, { count: number; windowStart: number }>();

  return {
    allow(key: string, nowMs: number): boolean {
      if (!map.has(key)) {
        map.set(key, { count: 1, windowStart: nowMs });
        return true;
      }
      const { count, windowStart } = map.get(key)!;
      if (nowMs - windowStart >= 1000) {
        map.set(key, { count: 1, windowStart: nowMs });
        return true;
      }
      if (count < 3) {
        map.set(key, { count: count + 1, windowStart });
        return true;
      }
      return false;
    },
    remaining(key: string, nowMs: number): number {
      const entry = map.get(key);
      if (!entry) return 3;
      return 3 - entry.count;
    },
    reset(key: string): void {
      map.delete(key);
    },
  };
}
