    if (!events.has(eventName)) {
      events.set(eventName, []);
    }
    events.get(eventName)!.push({ fn: listener, once: false });
  }

  function once(eventName: string, listener: Function): void {
    if (!events.has(eventName)) {
      events.set(eventName, []);
    }
    events.get(eventName)!.push({ fn: listener, once: true });
  }

  function off(eventName: string, listener: Function): boolean {
    if (!events.has(eventName)) {
      return false;
    }
    const listeners = events.get(eventName)!;
    const index = listeners.findIndex(item => item.fn === listener);
    if (index !== -1) {
      listeners.splice(index, 1);
      return true;
    }
    return false;
  }

  function emit(eventName: string, ...args: any[]): any[] {
    if (!events.has(eventName)) {
      return [];
    }
    const listeners = events.get(eventName)!;
    const results: any[] = [];
    const toRemove: number[] = [];

    for (let i = 0; i < listeners.length; i++) {
      const { fn, once } = listeners[i];
      const result = fn(...args);
      results.push(result);
      if (once) {
        toRemove.push(i);
      }
    }

    // Remove one-time listeners
    for (let i = toRemove.length - 1; i >= 0; i--) {
      listeners.splice(toRemove[i], 1);
    }

    return results;
  }

  return { on, once, off, emit };
