    allow(key: string, nowMs: number): boolean {
      const existing = state.get(key);

      if (!existing) {
        state.set(key, { count: 1, windowStartMs: nowMs });
        return true;
      }

      // Check if window has elapsed
      if (nowMs - existing.windowStartMs >= 1000) {
        // Start fresh window
        state.set(key, { count: 1, windowStartMs: nowMs });
        return true;
      }

      // Within window, check quota
      if (existing.count < 3) {
        // Increment and allow
        existing.count++;
        return true;
      }

      // Quota exceeded
      return false;
    },

    reset(key: string): void {
      state.delete(key);
    }
  };
}

export function createRateLimiter(): RateLimiter {
  const state = new Map<string, { windowStart: number; count: number }>();

  return {
    allow(key: string, nowMs: number): boolean {
      const keyState = state.get(key);
      let windowStart: number;
      let count: number;

      if (!keyState) {
        // First request for this key
        windowStart = nowMs;
        count = 0;
      } else {
        // Check if window has expired
        if (nowMs - keyState.windowStart >= 1000) {
          // Reset window
          windowStart = nowMs;
          count = 0;
        } else {
          windowStart = keyState.windowStart;
          count = keyState.count;
        }
      }

      if (count < 3) {
        // Allow the request
        state.set(key, { windowStart, count: count + 1 });
        return true;
      } else {
        // Reject the request
        return false;
      }
    },

    remaining(key: string, nowMs: number): number {
      const keyState = state.get(key);

      if (!keyState) {
        return 3;
      }

      if (nowMs - keyState.windowStart >= 1000) {
        // Window has expired
        return 3;
      } else {
        // Return remaining quota
        return Math.max(0, 3 - keyState.count);
      }
    },

    reset(key: string): void {
      state.delete(key);
    }
  };
}

