      const newTodos = todos.filter(todo => !todo.completed);
      todos.length = 0;
      todos.push(...newTodos);
    }
  };
}

export function createTodoApp(): TodoApp {
  let todos: Todo[] = [];
  let nextId = 1;
  const deletedIds: number[] = [];

  function addTodo(text: string): Todo {
    const id = deletedIds.length > 0 ? deletedIds.shift()! : nextId++;
    const todo: Todo = { id, text, completed: false };
    todos.push(todo);
    return todo;
  }

  function getTodo(id: number): Todo | undefined {
    return todos.find(todo => todo.id === id);
  }

  function toggleTodo(id: number): void {
    const todo = getTodo(id);
    if (todo) {
      todo.completed = !todo.completed;
    }
  }

  function deleteTodo(id: number): boolean {
    const index = todos.findIndex(todo => todo.id === id);
    if (index !== -1) {
      todos.splice(index, 1);
      deletedIds.push(id);
      return true;
    }
    return false;
  }

  function listTodos(): Todo[] {
    return [...todos];
  }

  function listCompleted(): Todo[] {
    return todos.filter(todo => todo.completed);
  }

  function listPending(): Todo[] {
    return todos.filter(todo => !todo.completed);
  }

  function clearCompleted(): void {
    const newTodos: Todo[] = [];
    for (const todo of todos) {
      if (!todo.completed) {
        newTodos.push(todo);
      } else {
        deletedIds.push(todo.id);
      }
    }
    todos = newTodos;
  }

  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
    clearCompleted
  };
}

interface Todo {
  id: number;
  text: string;
  completed: boolean;
}

interface TodoApp {
  addTodo(text: string): Todo;
  getTodo(id: number): Todo | undefined;
  toggleTodo(id: number): void;
  deleteTodo(id: number): boolean;
  listTodos(): Todo[];
  listCompleted(): Todo[];
  listPending(): Todo[];
  clearCompleted(): void;
}

