// Factory function to create a minimal event emitter with registration, once, off, and emit capabilities.
export function createEventEmitter() {
  // Internal storage: event -> Array of listeners (each listener is a function)
  const events = new Map<string, Array<Function>>();

  /**
   * Register an event listener.
   * @param event - The event name.
   * @param listener - The listener function.
   */
  function on(event: string, listener: Function): void {
    if (!events.has(event)) {
      events.set(event, []);
    }
    events.get(event)!.push(listener);
  }

  /**
   * Register a one-time listener.
   * @param event - The event name.
   * @param listener - The listener function.
   */
  function once(event: string, listener: Function): void {
    function wrapper(...args: any[]) {
      listener(...args);
      off(event, wrapper);
    }
    on(event, wrapper);
  }

  /**
   * Remove a specific listener.
   * @param event - The event name.
   * @param listener - The listener function to remove.
   */
  function off(event: string, listener: Function): void {
    const list = events.get(event);
    if (!list) return;
    const index = list.indexOf(listener);
    if (index !== -1) {
      list.splice(index, 1);
    }
  }

  /**
   * Emit an event, calling all listeners in registration order.
   * @param event - The event name.
   * @param args - Arguments to pass to listeners.
   * @returns The return values of all listeners in order.
   */
  function emit(event: string, ...args: any[]): any[] {
    const list = events.get(event);
    if (!list || list.length === 0) {
      return [];
    }
    const results: any[] = [];
    for (const listener of list) {
      results.push(listener(...args));
    }
    return results;
  }

  return {
    on,
    once,
    off,
    emit,
  };
}

// Export named function as default
export default createEventEmitter;
