export function createRateLimiter(): RateLimiter {
  const stores = new Map<string, { count: number; windowStart: number }>();

  return {
    allow(key: string, nowMs: number): boolean {
      const store = stores.get(key) || { count: 0, windowStart: -Infinity };
      const { count, windowStart } = store;
      if (nowMs - windowStart >= 1000 || count < 3) {
        stores.set(key, { count: Math.min(count + 1, 3), windowStart });
        return true;
      }
      return false;
    },
    remaining(key: string): number {
      const store = stores.get(key) || { count: 0, windowStart: -Infinity };
      if (store.count < 3 && (Date.now() - store.windowStart) < 1000) {
        return 3 - store.count;
      }
      return 0;
    },
    reset(key: string) {
      stores.delete(key);
    }
  };
}

interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string): number;
  reset(key: string): void;
}
