/**
 * A simple in-memory todo application manager with the following features:
 * - Add new todos with auto-incrementing IDs
 * - Get specific todos by ID
 * - Toggle completion status of todos
 * - Delete todos by ID
 * - List all todos, completed todos, and pending todos
 * - Clear all completed todos without affecting pending todos
 *
 * Design Notes:
 * - No external storage: All data is managed within the instance lifecycle of the app.
 * - Uses `createTodoApp()` pattern for clean functional composition.
 * - Exports a single factory function `createTodoApp()` that returns the API.
 */
export function createTodoApp() {
  /**
   * Manages all todos with an internal counter to ensure unique IDs.
   * Never reused after deletion.
   */
  const todos: [id: number, text: string, completed: boolean][] = [];
  let nextId = 1;

  /**
   * Finds the index of a todo by its ID.
   * Returns -1 if not found.
   */
  function findIndex(id: number) {
    return todos.findIndex(([tid]) => tid === id);
  }

  /**
   * Helper: returns the current internal todos as readonly tuples:
   * Each tuple: [id, text, completed].
   */
  function asList(): readonly [id: number, text: string, completed: boolean][] {
    return [...todos];
  }

  /**
   * Implements the required API:
   * - addTodo
   * - getTodo
   * - toggleTodo
   * - deleteTodo
   * - listTodos
   * - listCompleted
   * - listPending
   * - clearCompleted
   */
  const api = {
    /**
     * Creates a new todo with provided text and returns its full object:
     * { id, text, completed }
     */
    addTodo: (text: string) => {
      const id = nextId++;
      const completed = false;
      // push to start for performance: O(1) amortized (Array.push is O(1) amortized).
      todos.push([id, text, completed]);
      return { id, text, completed };
    },

    /**
     * Returns the todo object for a given ID, or undefined if not found.
     */
    getTodo: (id: number): { id: number, text: string, completed: boolean } | undefined => {
      const idx = findIndex(id);
      if (idx === -1) return undefined;
      const [idn, text, completed] = todos[idx];
      return { id: idn, text, completed };
    },

    /**
     * Toggles the completed status of the todo. No-op if not found.
     * Does NOT throw.
     */
    toggleTodo: (id: number): void => {
      const idx = findIndex(id);
      if (idx === -1) return;
      todos[idx] = [...todos[idx], !(todos[idx][2])];
    },

    /**
     * Deletes the todo by id. Returns true if deleted, false if not found.
     */
    deleteTodo: (id: number): boolean => {
      const idx = findIndex(id);
      if (idx === -1) return false;
      todos.splice(idx, 1);
      return true;
    },

    /**
     * Returns all todos (shallow copy).
     */
    listTodos: () => asList(),

    /**
     * Returns todos that have completed status true.
     */
    listCompleted: () => asList().filter(([_id, _text, completed]) => completed),

    /**
     * Returns todos that have completed status false.
     */
    listPending: () => asList().filter(([_id, _text, completed]) => !completed),

    /**
     * Removes all todos that are completed. Returns true if any removed, false if none were completed.
     * It avoids mutating the array while iterating by iterating in reverse by index.
     */
    clearCompleted: () => {
      let had = false;
      for (let i = todos.length - 1; i >= 0; i--) {
        if (todos[i][2]) {
          todos.splice(i, 1);
          had = true;
        }
      }
      return had;
    },
  };
  return api;
}
