/**
 * Creates a TTL cache instance with the specified TTL.
 *
 * @returns An object with methods to manage the cache.
 */
export function createTtlCache() {
  /**
   * Entries stored in the cache.
   * Key is the string key, value is an entry with value, expiration time, and insertion time.
   */
  const entries = new Map<string, { value: unknown; expiresAt: number; insertedAt: number }>();

  /**
   * Sets the value for a key, with optional TTL.
   * Overwrites existing entries and updates expiration.
   *
   * @param key - The key to store the value under.
   * @param value - The value to store.
   * @param nowMs - The current timestamp in milliseconds.
   * @param ttlMs - Optional TTL in milliseconds. Defaults to 1000 if not provided.
   */
  function set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
    const ttl = ttlMs ?? 1000; // Default TTL of 1000ms
    const expiresAt = nowMs + ttl;
    const insertedAt = nowMs;
    entries.set(key, { value, expiresAt, insertedAt });
  }

  /**
   * Gets the value for a key.
   * Returns undefined if the key does not exist or is expired.
   *
   * @param key - The key to retrieve the value for.
   * @param nowMs - The current timestamp in milliseconds.
   * @returns The value or undefined if expired or not found.
   */
  function get(key: string, nowMs: number): unknown {
    const entry = entries.get(key);
    if (!entry || nowMs >= entry.expiresAt) {
      entries.delete(key); // Remove expired or missing entry
      return undefined;
    }
    return entry.value;
  }

  /**
   * Checks if a key exists and is not expired.
   *
   * @param key - The key to check.
   * @param nowMs - The current timestamp in milliseconds.
   * @returns True if the key exists and is valid.
   */
  function has(key: string, nowMs: number): boolean {
    const entry = entries.get(key);
    if (!entry || nowMs >= entry.expiresAt) {
      entries.delete(key); // Remove expired or missing entry
      return false;
    }
    return true;
  }

  /**
   * Deletes a key from the cache.
   *
   * @param key - The key to delete.
   * @returns True if the key existed and was removed.
   */
  function deleteKey(key: string): boolean {
    return entries.delete(key);
  }

  /**
   * Returns the number of valid (non-expired) entries.
   *
   * @param nowMs - The current timestamp in milliseconds.
   * @returns The count of valid entries.
   */
  function size(nowMs: number): number {
    let count = 0;
    for (const [key, entry] of entries) {
      if (nowMs < entry.expiresAt) {
        count++;
      } else {
        entries.delete(key); // Clean up expired entries
      }
    }
    return count;
  }

  /**
   * Clears all entries.
   */
  function clear(): void {
    entries.clear();
  }

  return {
    set,
    get,
    has,
    delete: deleteKey,
    size,
    clear,
  };
}
