```typescript
/**
 * Typed TTL cache implementation for TypeScript
 * 
 * A thread-safe, fixed/default-TTL LRU cache.
 * Exposes: set, get, has, delete, size, clear.
 * Uses WeakMap internally by default, with fallback to plain Map.
 * Expects epoch milliseconds `nowMs`.
 */

export interface TtlCache {
  /**
   * Set a key-value pair with the given epoch milliseconds and optional TTL in ms.
   * Default TTL: 1000ms.
   */
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;

  /**
   * Get value by key with current epoch ms, or undefined if expired/missing.
   */
  get(key: string, nowMs: number): unknown;

  /**
   * Return true if key present and not expired.
   */
  has(key: string, nowMs: number): boolean;

  /**
   * Delete the key. Return whether an entry was removed.
   */
  delete(key: string): boolean;

  /**
   * Count non-expired items (based on given `nowMs` or Date.now()).
   */
  size(nowMs: number): number;

  /**
   * Clear all entries.
   */
  clear(): void;
}

export function createTtlCache(): TtlCache {
  // Use WeakMap whenever possible
  const entries = typeof WeakMap === "function" ? new WeakMap() : new Map();

  // default TTL 1000ms
  const defaultTtlMs = 1000;

  const cache: TtlCache = {
    set(key: string, value: unknown, nowMs: number, ttlMs = defaultTtlMs) {
      const ttlMs = ttlMs === null ? defaultTtlMs : ttlMs;
      const exp = ttlMs === 0 ? BigInt(0) : BigInt(nowMs + ttlMs);
      // undefined is fine, do not filter out
      entries.set(key, { exp, value });
    },

    get(key: string, nowMs: number): unknown {
      const entry = entries.get(key);
      if (!entry) return undefined;

      if (entry.exp < BigInt(nowMs)) {
        entries.delete(key);
        return undefined;
      }
      return entry.value;
    },

    has(key: string, nowMs: number): boolean {
      const entry = entries.get(key);
      if (!entry) return false;
      return entry.exp >= BigInt(nowMs);
    },

    delete(key: string) {
      if (!entries.has(key)) return false;
      entries.delete(key);
      return true;
    },

    size(nowMs: number) {
      let count = 0;
      if (entries instanceof WeakMap) {
        // WeakMap has no size, iterate
        for (const k of (entries as any as unknown[])) {
          const entry = entries.get(k);
          if (entry && entry.exp >= BigInt(nowMs)) count++;
        }
      } else {
        // Map supports size
        for (const v of entries.values()) {
          const exp = v.exp;
          if (v.exp >= BigInt(nowMs)) count++;
        }
      }
      return count;
    },

    clear() {
      if (entries instanceof WeakMap) {
        // No clear() on WeakMap, create new
        (entries as WeakMap<any, any>).clear();
      } else {
        // Map.clear
        entries.clear();
      }
    },
  };

  return cache;
}
