export interface RateLimiter {
  reset(key: string): void;
  rateLimit(key: string, nowMs: number): boolean;
}

export function createRateLimiter(key: string, nowMs: number): RateLimiter {
  const instance: RateLimiter = {
    reset: (k: string) => {
      if (k === key) {
        this.nextAllowed = nowMs + 1000;
        this.count = 0;
      }
    },
    rateLimit: (k: string, nowMs: number): boolean => {
      if (k !== key) return false;

      if (nowMs < this.nextAllowed) {
        this.count++;
        if (this.count >= 3) {
          this.nextAllowed = nowMs + 1000;
          this.count = 0;
        }
      } else {
        this.count = 0;
      }

      return this.count < 3;
    }
  };

  this.nextAllowed = nowMs + 1000;
  this.count = 0;
  return instance;
}
