export function createTtlCache() {
  const cache = new Map();

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number) {
      const expiresAt = nowMs + (ttlMs ?? 1000);
      cache.set(key, { value, expiresAt });
    },

    get(key: string, nowMs: number) {
      const entry = cache.get(key);
      if (!entry) return undefined;
      const expiresAt = entry.expiresAt;
      return expiresAt > nowMs ? entry.value : undefined;
    },

    has(key: string, nowMs: number) {
      const entry = cache.get(key);
      return entry && entry.expiresAt > nowMs;
    },

    delete(key: string) {
      const entry = cache.delete(key);
      return entry;
    },

    size(nowMs: number) {
      let count = 0;
      for (const [key, { expiresAt }] of cache.entries()) {
        if (expiresAt > nowMs) count++;
      }
      return count;
    },

    clear() {
      cache.clear();
    }
  };
}
