```typescript
type Listener<T = any> = (event: T) => void | T;

export function createEventEmitter() {
  const listeners: { [EventName: string]: Array<Listener> } = {};

  function emit<T>(eventName: string, eventData: T): T[] {
    const listenersForEvent = listeners[eventName] || [];
    const results: T[] = [];
    for (const listener of listenersForEvent) {
      const result = listener(eventData);
      if (typeof result !== 'undefined') {
        results.push(result);
      }
    }
    return results;
  }

  function off<T>(eventName: string, listener: Listener<T>): void {
    const existingListeners = listeners[eventName] || [];
    listeners[eventName] = existingListeners.filter(
      (l) => l.toString() !== listener.toString()
    );
  }

  function once<T>(eventName: string, listener: Listener<T>): void {
    let emitted = false;
    const wrapListener = (data: T): T => {
      const result = listener(data);
      if (!emitted) {
        emitted = true;
        off(eventName, wrapListener as unknown as Listener);
      }
      return result;
    };
    listeners[eventName] = listeners[eventName] || [];
    listeners[eventName].push(wrapListener);
  }

  function on<T>(eventName: string, listener: Listener<T>): void {
    listeners[eventName] = listeners[eventName] || [];
    listeners[eventName].push(listener);
  }

  return {
    on,
    off,
    once,
    emit,
  };
}
