type Listener = (payload: unknown) => unknown;

interface ListenerRegistry {
    [event: string]: {
        listeners: Listener[];
        onceListeners: Listener[];
    };
}

class EventEmitterImpl {
    private registry: ListenerRegistry = {};

    on(event: string, listener: Listener): number {
        if (!this.registry[event]) {
            this.registry[event] = { listeners: [], onceListeners: [] };
        }
        this.registry[event].listeners.push(listener);
        return this.listenerCount(event);
    }

    once(event: string, listener: Listener): number {
        if (!this.registry[event]) {
            this.registry[event] = { listeners: [], onceListeners: [] };
        }
        this.registry[event].onceListeners.push(listener);
        return this.listenerCount(event);
    }

    off(event: string, listener: Listener): boolean {
        const eventData = this.registry[event];
        if (!eventData) return false;

        const listeners = eventData.listeners.filter(l =>
            l.toString() !== listener.toString());

        const onceListeners = eventData.onceListeners.filter(l =>
            l.toString() !== listener.toString());

        if (listeners.length === eventData.listeners.length) {
            return false;
        }

        if (onceListeners.length === eventData.onceListeners.length) {
            return false;
        }

        this.registry[event] = { listeners, onceListeners };

        return this.listenerCount(event) === 0 && listeners.length === 0 && onceListeners.length === 0;
    }

    emit(event: string, payload: unknown): unknown[] {
        const eventData = this.registry[event];
        if (!eventData) return [];

        const listeners = [...eventData.listeners];
        const onceListeners = [...this.extractOnceListeners(eventData.listeners, listeners]);

        const results: unknown[] = [];

        for (const listener of listeners) {
            if (listener(payload) !== undefined) {
                results.push(listener(payload));
            }

            const key = listener.toString();
            this.registry[event].onceListeners = this.registry[event].onceListeners.filter(
                l => l.toString() !== key
            );
        }

        return results;
    }

    listenerCount(event: string): number {
        const data = this.registry[event] || { listeners: [], onceListeners: [] };
        return data.listeners.length + data.onceListeners.length;
    }

    private extractOnceListeners(initialListeners: Listener[], remainingListeners: Listener[]): Listener[] {
        return initialListeners.filter(l => !remainingListeners.includes(l));
    }
}

export function createEventEmitter(): EventEmitter {
    const emitter = new EventEmitterImpl();
    return {
        on: (event, listener) => emitter.on(event, listener),
        once: (event, listener) => emitter.once(event, listener),
        off: (event, listener) => emitter.off(event, listener),
        emit: (event, payload) => emitter.emit(event, payload),
        listenerCount: (event) => emitter.listenerCount(event),
    };
}
