export function createTodoApp() {
    const todos: Record<number, { text: string; completed: boolean }> = {};
    let nextId = 1;

    function getTodo(id: number): { id: number; text: string; completed: boolean } | undefined {
        return { id, text: todos[id]?.text || '', completed: todos[id]?.completed || false };
    }

    function addTodo(text: string): { id: number; text: string; completed: boolean } {
        const newTodo: { id: number; text: string; completed: boolean } = {
            id: nextId++,
            text,
            completed: false
        };
        todos[newTodo.id] = { text: newTodo.text, completed: newTodo.completed };
        return newTodo;
    }

    function toggleTodo(id: number): void {
        if (!todos[id]) return;
        todos[id].completed = !todos[id].completed;
    }

    function deleteTodo(id: number): boolean {
        if (!todos[id]) return false;
        delete todos[id];
        return true;
    }

    function listTodos(): Array<{ id: number; text: string; completed: boolean }> {
        return Object.values(todos).map(item => ({ id: Object.keys(todos).find(key => todos[key] === item)!,
                                                        text: item.text,
                                                        completed: item.completed }));
    }

    function listCompleted(): Array<{ id: number; text: string; completed: boolean }> {
        return Object.values(todos).filter(item => item.completed).map(completedItem =>
            ({ id: Object.keys(todos).find(key => todos[key] === completedItem)!,
                    text: completedItem.text,
                    completed: true}));
    }

    function listPending(): Array<{ id: number; text: string; completed: boolean }> {
        return Object.values(todos).filter(item => !item.completed).map(pendingItem =>
            ({ id: Object.keys(todos).find(key => todos[key] === pendingItem)!,
                    text: pendingItem.text,
                    completed: false}));
    }

    function clearCompleted(): void {
        for (const id of Object.keys(todos)) {
            if (todos[id].completed) {
                delete todos[id];
            }
        }
    }

    return {
        addTodo,
        getTodo,
        toggleTodo,
        deleteTodo,
        listTodos,
        listCompleted,
        listPending,
        clearCompleted
    };
}
