type TtlCacheEntry = {
  value: unknown;
  expiresAt: number;
};

class DeterministicTtlCache {
  private storage: Map<string, TtlCacheEntry>;
  private defaultTtlMs: number;

  constructor(defaultTtlMs: number = 1000) {
    this.storage = new Map();
    this.defaultTtlMs = defaultTtlMs;
  }

  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
    const expiryMs = ttlMs ?? this.defaultTtlMs;
    this.storage.set(key, { value, expiresAt: nowMs + expiryMs });
  }

  get(key: string, nowMs: number): unknown {
    const entry = this.storage.get(key);
    return entry?.expiresAt > nowMs ? entry.value : undefined;
  }

  has(key: string, nowMs: number): boolean {
    const entry = this.storage.get(key);
    return entry?.expiresAt > nowMs ? true : false;
  }

  delete(key: string): boolean {
    const deleted = this.storage.delete(key);
    return deleted;
  }

  size(nowMs: number): number {
    return Array.from(this.storage.values())
      .filter((entry) => entry.expiresAt > nowMs)
      .length;
  }

  clear(): void {
    this.storage.clear();
  }
}

export function createTtlCache() {
  return new DeterministicTtlCache();
}
