class EventEmitter {
  private listeners: { [eventName: string]: (args: any) => any[] } = {};

  public on(eventName: string, listener: (args: any) => any[]) {
    if (!this.listeners[eventName]) {
      this.listeners[eventName] = [];
    }
    this.listeners[eventName].push(listener);
    return () => {
      const index = this.listeners[eventName].indexOf(listener);
      if (index !== -1) {
        this.listeners[eventName].splice(index, 1);
      }
    };
  }

  public once(eventName: string, listener: (args: any) => any[]) {
    const listenerWrapper = (...args: any[]) => {
      const result = listener(...args);
      this.off(eventName, listenerWrapper);
      return result;
    };
    this.on(eventName, listenerWrapper);
    return () => {
      this.off(eventName, listenerWrapper);
    };
  }

  public off(eventName: string, listener: (args: any) => any) {
    if (!this.listeners[eventName]) {
      return;
    }
    const index = this.listeners[eventName].indexOf(listener);
    if (index !== -1) {
      this.listeners[eventName].splice(index, 1);
    }
  }

  public emit(eventName: string, ...args: any[]) {
    if (this.listeners[eventName]) {
      return this.listeners[eventName].map((listener) => listener(...args));
    }
    return [];
  }
}

export function createEventEmitter(): { emitter: EventEmitter } {
  return { emitter: new EventEmitter() };
}
