export function createEventEmitter() {
  const events = new Map<string, { callback: Function; isOnce: boolean }[]>();
  return {
    on(event: string, callback: Function) {
      events.set(event, [...events.get(event) || [], { callback, isOnce: false }]);
    },
    once(event: string, callback: Function) {
      events.set(event, [...events.get(event) || [], { callback, isOnce: true }]);
    },
    off(event: string, callback: Function) {
      const list = events.get(event);
      if (list) {
        const index = list.findIndex(listener => listener.callback === callback);
        if (index !== -1) {
          list.splice(index, 1);
        }
      }
    },
    emit(event: string, ...args: any[]) {
      const list = events.get(event);
      if (list) {
        const results = [];
        for (const listener of list) {
          results.push(listener.callback(...args));
          if (listener.isOnce) {
            const index = list.indexOf(listener);
            list.splice(index, 1);
          }
        }
        return results;
      }
      return [];
    }
  };
