type Listener = (payload: unknown) => unknown;

interface EventEmitter {
  on(event: string, listener: Listener): number;
  once(event: string, listener: Listener): number;
  off(event: string, listener: Listener): boolean;
  emit(event: string, payload: unknown): unknown[];
  listenerCount(event: string): number;
}

export function createEventEmitter(): EventEmitter {
  const eventMap = new Map<string, { regular: Listener[]; once: Listener[] }>();

  return {
    on(event: string, listener: Listener): number {
      if (!eventMap.has(event)) {
        eventMap.set(event, { regular: [], once: [] });
      }
      eventMap.get(event)!.regular.push(listener);
      return eventMap.get(event)!.regular.length + eventMap.get(event)!.once.length;
    },
    once(event: string, listener: Listener): number {
      if (!eventMap.has(event)) {
        eventMap.set(event, { regular: [], once: [] });
      }
      eventMap.get(event)!.once.push(listener);
      return eventMap.get(event)!.regular.length + eventMap.get(event)!.once.length;
    },
    off(event: string, listener: Listener): boolean {
      const eventDetails = eventMap.get(event);
      if (!eventDetails) return false;

      const index = eventDetails.regular.indexOf(listener);
      if (index !== -1) {
        eventDetails.regular.splice(index, 1);
        return true;
      }

      const onceIndex = eventDetails.once.indexOf(listener);
      if (onceIndex !== -1) {
        eventDetails.once.splice(onceIndex, 1);
        return true;
      }

      return false;
    },
    emit(event: string, payload: unknown): unknown[] {
      const eventDetails = eventMap.get(event);
      if (!eventDetails) return [];

      const results: unknown[] = [];

      // Process regular listeners
      for (const listener of eventDetails.regular) {
        results.push(listener(payload));
      }

      // Process once listeners
      const onceCopy = [...eventDetails.once];
      for (const listener of onceCopy) {
        results.push(listener(payload));
        const index = eventDetails.once.indexOf(listener);
        if (index !== -1) {
          eventDetails.once.splice(index, 1);
        }
      }

      return results;
    },
    listenerCount(event: string): number {
      const eventDetails = eventMap.get(event);
      return eventDetails ? eventDetails.regular.length + eventDetails.once.length : 0;
    }
  };
}
