const windowMs = 1000;
const limit = 3;

interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}

export function createRateLimiter(): RateLimiter {
  const state = new Map<string, { windowStart: number; count: number }>();

  return {
    allow(key: string, nowMs: number): boolean {
      const stateEntry = state.get(key);
      if (!stateEntry) {
        state.set(key, { windowStart: nowMs, count: 0 });
        return true;
      }

      const diff = nowMs - stateEntry.windowStart;
      if (diff >= windowMs) {
        state.set(key, { windowStart: nowMs, count: 0 });
      }

      const count = stateEntry.count;
      if (count < limit) {
        state.set(key, { windowStart: stateEntry.windowStart, count: count + 1 });
        return true;
      }
      return false;
    },
    remaining(key: string, nowMs: number): number {
      const stateEntry = state.get(key);
      return stateEntry ? limit - stateEntry.count : 0;
    },
    reset(key: string): void {
      state.delete(key);
    }
  };
}
