export function createEventEmitter() {
    type Listener<Args extends any[]> = (...args: Args) => unknown;
    type EventHandlers<Args extends any[]> = Array<Listener<Args>>;

    const events = new Map<string, EventHandlers<any[]>>();

    return {
        on<Args extends any[]>(
            event: string,
            listener: Listener<Args>
        ): void {
            const handlers = events.get(event) ?? [];
            handlers.push(listener);
            if (!events.has(event)) {
                events.set(event, handlers);
            }
        },
        once<Args extends any[]>(
            event: string,
            listener: Listener<Args>
        ): void {
            const handlers = events.get(event) ?? [];
            const wrapper = (...args: Args) => {
                listener(...args);
                const index = handlers.indexOf(wrapper);
                if (index !== -1) {
                    handlers.splice(index, 1);
                }
            };
            handlers.push(wrapper);
            if (!events.has(event)) {
                events.set(event, handlers);
            }
        },
        off<Args extends any[]>(
            event: string,
            listener?: Listener<Args>
        ): void {
            if (!listener) {
                events.delete(event);
                return;
            }
            const handlers = events.get(event);
            if (!handlers) return;
            handlers.forEach((h, index) => {
                if (h === listener) {
                    handlers.splice(index, 1);
                }
            });
            if (handlers.length === 0) {
                events.delete(event);
            }
        },
        emit<Args extends any[]>(
            event: string,
            ...args: Args
        ): unknown[] {
            const handlers = events.get(event);
            if (!handlers) return [];
            return handlers.map((handler) => handler(...args));
        }
    };
}
