export function createEventEmitter(): EventEmitter {
  const registrations: Map<
    string,
    Array<{ listener: Listener; once: boolean }>
  > = new Map();

  return {
    on(event: string, listener: Listener): number {
      const listeners = registrations.get(event) || [];
      listeners.push({ listener, once: false });
      registrations.set(event, listeners);
      return listeners.length;
    },
    once(event: string, listener: Listener): number {
      const listeners = registrations.get(event) || [];
      listeners.push({ listener, once: true });
      registrations.set(event, listeners);
      return listeners.length;
    },
    off(event: string, listener: Listener): boolean {
      const listeners = registrations.get(event);
      if (!listeners) return false;

      const index = listeners.findIndex((l) => l.listener === listener);
      if (index === -1) return false;

      listeners.splice(index, 1);
      return true;
    },
    emit(event: string, payload: unknown): unknown[] {
      const listeners = registrations.get(event) || [];
      const results: unknown[] = [];
      const newListeners: Array<{ listener: Listener; once: boolean }> = [];

      for (const { listener, once } of listeners) {
        results.push(listener(payload));
        if (!once) {
          newListeners.push({ listener, once });
        }
      }

      registrations.set(event, newListeners);
      return results;
    },
    listenerCount(event: string): number {
      return registrations.get(event)?.length || 0;
    },
  };
}

type Listener = (payload: unknown) => unknown;

interface EventEmitter {
  on(event: string, listener: Listener): number;
  once(event: string, listener: Listener): number;
  off(event: string, listener: Listener): boolean;
  emit(event: string, payload: unknown): unknown[];
  listenerCount(event: string): number;
}
