type RateLimiter = {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
}

export function createRateLimiter(): RateLimiter {
  const state: Record<string, { windowStart: number; used: number }> = {}

  return {
    allow(key: string, nowMs: number): boolean {
      const entry = state[key] || { windowStart: nowMs, used: 0 }
      if (nowMs - entry.windowStart >= 1000 || entry.windowStart === nowMs) {
        entry.windowStart = nowMs
        entry.used = 0
      } else {
        state[key] = entry
      }

      const allowed = entry.used < 3
      if (allowed) {
        entry.used += 1
        state[key] = entry
      }
      return allowed
    },
    remaining(key: string, nowMs: number): number {
      const entry = state[key] || { windowStart: nowMs, used: 0 }
      if (nowMs - entry.windowStart >= 1000) {
        return 3
      } else {
        return Math.max(0, 3 - entry.used)
      }
    },
    reset(key: string): void {
      delete state[key]
    },
  }
}
