  const cache: Record<string, CacheEntry> = {};

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs: number = 1000): void {
      const expiresAt = nowMs + ttlMs;
      cache[key] = { value, expiresAt };
    },

    get(key: string, nowMs: number): unknown {
      const entry = cache[key];
      if (entry && nowMs < entry.expiresAt) {
        return entry.value;
      }
      return undefined;
    },

    has(key: string, nowMs: number): boolean {
      const entry = cache[key];
      return !!(entry && nowMs < entry.expiresAt);
    },

    delete(key: string): boolean {
      const hadKey = key in cache;
      delete cache[key];
      return hadKey;
    },

    size(nowMs: number): number {
      return Object.values(cache).filter(
        (entry) => nowMs < entry.expiresAt
      ).length;
    },

    clear(): void {
      Object.keys(cache).forEach((key) => delete cache[key]);
    },
  };
}
