export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
} {
  const map = new Map<string, {value: any; expiresAt: number}>();
  const defaultTTL = 1000;
  return {
    set(key, value, nowMs, ttlMs) {
      const expiresAt = nowMs + (ttlMs ?? defaultTTL);
      map.set(key, {value, expiresAt});
    },
    get(key, nowMs) {
      const entry = map.get(key);
      return entry && nowMs < entry.expiresAt ? entry.value : undefined;
    },
    has(key, nowMs) {
      const entry = map.get(key);
      return entry && nowMs < entry.expiresAt;
    },
    delete(key) {
      return map.delete(key);
    },
    size(nowMs) {
      let count = 0;
      for (const {expiresAt} of map.values()) {
        if (nowMs < expiresAt) count++;
      }
      return count;
    },
    clear() {
      map.clear();
    },
  };
}

export interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
}

export function createTtlCache(): TtlCache {
  const entries = new Map<string, {value: unknown; expiresAt: number}>();

  return {
    set(key, value, nowMs, ttlMs) {
      const defaultTTL = 1000;
      const ttl = ttlMs !== undefined ? ttlMs : defaultTTL;
      const expiresAt = ttlMs === 0 ? nowMs : nowMs + ttl;
      entries.set(key, {value, expiresAt});
    },

    get(key, nowMs) {
      const entry = entries.get(key);
      if (!entry) return undefined;
      if (nowMs >= entry.expiresAt) {
        entries.delete(key);
        return undefined;
      }
      return entry.value;
    },

    has(key, nowMs) {
      const entry = entries.get(key);
      return entry && nowMs < entry.expiresAt;
    },

    delete(key) {
      return entries.delete(key);
    },

    size(nowMs) {
      let count = 0;
      for (const {expiresAt} of entries.values()) {
        if (nowMs < expiresAt) count++;
      }
      return count;
    },

    clear() {
      entries.clear();
    },
  };
}

