type Listener = (...args: any[]) => any;
type ListenerWrapper = { listener: Listener; once: boolean };

interface EventEmitter {
  on(eventName: string, listener: Listener): void;
  off(eventName: string, listener: Listener): void;
  once(eventName: string, listener: Listener): void;
  emit(eventName: string, ...args: any[]): any[];
}

export function createEventEmitter(): EventEmitter {
  const listeners: Map<string, ListenerWrapper[]> = new Map();

  return {
    on(eventName: string, listener: Listener): void {
      const eventListeners = listeners.get(eventName) || [];
      eventListeners.push({ listener, once: false });
      listeners.set(eventName, eventListeners);
    },

    off(eventName: string, listener: Listener): void {
      const eventListeners = listeners.get(eventName);
      if (eventListeners) {
        for (let i = 0; i < eventListeners.length; i++) {
          if (eventListeners[i].listener === listener) {
            eventListeners.splice(i, 1);
            break;
          }
        }
        listeners.set(eventName, eventListeners);
      }
    },

    once(eventName: string, listener: Listener): void {
      const eventListeners = listeners.get(eventName) || [];
      eventListeners.push({ listener, once: true });
      listeners.set(eventName, eventListeners);
    },

    emit(eventName: string, ...args: any[]): any[] {
      const eventListeners = listeners.get(eventName) || [];
      const results: any[] = [];
      const onceListenersCopy = [...eventListeners];

      for (const wrapper of onceListenersCopy) {
        if (wrapper.once || !wrapper.once) {
          const result = wrapper.listener(...args);
          results.push(result);

          if (wrapper.once) {
            for (let i = 0; i < eventListeners.length; i++) {
              const w = eventListeners[i];
              if (w.listener === wrapper.listener && w.once) {
                eventListeners.splice(i, 1);
                break;
              }
            }
          }
        }
      }

      return results;
    },
  };
}
