type RateLimiterPolicy = {
    requests: number;
    windowMs: number;
};

type RateLimiterConfig = {
    nowMs: () => number;
    policy: RateLimiterPolicy;
};

type RateLimiter = {
    isRateLimited(key: string): boolean;
    reset(key: string): void;
};

function createRateLimiter(config: RateLimiterConfig): RateLimiter {
    const { nowMs, policy } = config;
    const { requests, windowMs } = policy;

    const state: Map<string, { count: number; resetTimeMs: number }> = new Map();

    function isRateLimited(key: string): boolean {
        const now = nowMs();
        const entry = state.get(key);

        if (!entry) {
            state.set(key, { count: 1, resetTimeMs: now });
            return false;
        }

        if (now - entry.resetTimeMs >= windowMs) {
            entry.count = 1;
            entry.resetTimeMs = now;
            return false;
        }

        if (entry.count >= requests) {
            return true;
        }

        entry.count += 1;
        return false;
    }

    function reset(key: string): void {
        const entry = state.get(key);
        if (entry) {
            entry.count = 0;
            state.delete(key);
        }
    }

    return { isRateLimited, reset };
}
