export type RateLimiter = {
  canConsume(key: string, nowMs: number): boolean;
  reset(key: string): void;
};

export function createRateLimiter(): RateLimiter {
  const windowLengthMs = 1000;
  const maxRequests = 3;
  const requestMap = new Map<string, { requests: number; lastReset: number }>();

  return {
    canConsume(key: string, nowMs: number): boolean {
      if (!requestMap.has(key)) {
        requestMap.set(key, { requests: 1, lastReset: nowMs });
        return true;
      }

      const { requests, lastReset } = requestMap.get(key)!;

      if (nowMs - lastReset >= windowLengthMs) {
        requestMap.set(key, { requests: 1, lastReset: nowMs });
        return true;
      }

      if (requests < maxRequests) {
        requestMap.set(key, { requests: requests + 1, lastReset });
        return true;
      }

      return false;
    },
    reset(key: string): void {
      requestMap.delete(key);
    },
  };
}
