export function createRateLimiter(): RateLimiter {
  const limits = new Map<string, { limit: number; windowMs: number; windowStart: number; count: number }>();

  function allow(key: string, nowMs: number): boolean {
    if (!limits.has(key)) {
      limits.set(key, { limit: 3, windowMs: 1000, windowStart: nowMs, count: 1 });
      return true;
    }

    const { limit, windowMs, windowStart, count } = limits.get(key)!;

    if (nowMs - windowStart >= windowMs) {
      limits.set(key, { limit, windowMs, windowStart: nowMs, count: 1 });
      return true;
    }

    if (count < limit) {
      limits.set(key, { limit, windowMs, windowStart, count: count + 1 });
      return true;
    }

    return false;
  }

  function remaining(key: string, nowMs: number): number {
    if (!limits.has(key)) {
      return 0;
    }

    const { limit, windowMs, windowStart, count } = limits.get(key)!;

    if (nowMs - windowStart >= windowMs) {
      limits.set(key, { limit, windowMs, windowStart: nowMs, count: 1 });
      return limit - 1;
    }

    return limit - count;
  }

  function reset(key: string): void {
    limits.delete(key);
  }

  return { allow, remaining, reset };
}
