import { Listener } from './types';

export function createEventEmitter(): EventEmitter {
  const listeners = new Map<string, Set<Listener>>();
  return {
    on(event, listener) {
      if (!listeners.has(event)) listeners.set(event, new Set());
      listeners.get(event)!.add(listener);
      return listenerCount(event);
    },
    once(event, listener) {
      const wrapper = (...args) => {
        const res = listener(...args);
        off(event, wrapper);
        return res;
      };
      return on(event, wrapper);
    },
    off(event, listener) {
      if (!listeners.has(event)) return false;
      const eventListeners = listeners.get(event) || new Set();
      return eventListeners.delete(listener);
    },
    emit(event, payload) {
      const eventListeners = listeners.get(event) || new Set();
      const results: unknown[] = [];
      for (const l of eventListeners) results.push(l(payload));
      return results;
    },
    listenerCount(event) {
      return (listeners.get(event)?.size || 0);
    }
  };
}

export type Listener = (payload: unknown) => unknown;

export interface EventEmitter {
  on(event: string, listener: Listener): number;
  once(event: string, listener: Listener): number;
  off(event: string, listener: Listener): boolean;
  emit(event: string, payload: unknown): unknown[];
  listenerCount(event: string): number;
}
