export function createTtlCache(): TtlCache {
  const cache: Record<string, { value: unknown; ttlMs: number; expirationMs: number }> = {};

  return {
    set(key, value, nowMs, ttlMs = 1000) {
      if (ttlMs === 0) {
        this.delete(key);
      } else {
        const expirationMs = nowMs + ttlMs;
        cache[key] = { value, ttlMs, expirationMs };
      }
    },
    get(key, nowMs) {
      if (this.has(key, nowMs)) {
        return cache[key].value;
      }
      return undefined;
    },
    has(key, nowMs) {
      return key in cache && cache[key].expirationMs > nowMs;
    },
    delete(key) {
      if (key in cache) {
        delete cache[key];
        return true;
      }
      return false;
    },
    size(nowMs) {
      return Object.keys(cache).filter((k) => cache[k].expirationMs > nowMs).length;
    },
    clear() {
      cache = {};
    },
  };
}
