function createEventEmitter() {
  const events = new Map<string, Array<{ callback: Function; once: boolean }>>();

  return {
    on(event: string, listener: Function, options: { once: boolean } = { once: false }): void {
      if (!events.has(event)) {
        events.set(event, []);
      }
      events.get(event)!.push({ callback: listener, once: options.once });
    },
    off(event: string, listener: Function): void {
      const listeners = events.get(event);
      if (!listeners) return;
      const index = listeners.findIndex((l) => l.callback === listener);
      if (index !== -1) {
        listeners.splice(index, 1);
      }
    },
    emit(event: string, ...args: any[]): any[] {
      const listeners = events.get(event) || [];
      const results: any[] = [];
      const toRemove: { callback: Function; once: boolean }[] = [];

      for (const listener of listeners) {
        const result = listener.callback(...args);
        results.push(result);
        if (listener.once) {
          toRemove.push(listener);
        }
      }

      for (const listener of toRemove) {
        const index = listeners.indexOf(listener);
        if (index !== -1) {
          listeners.splice(index, 1);
        }
      }

      return results;
    },
  };
