export function createEventEmitter(): any {
  class EventEmitter {
    private listeners = new Map<string, Array<{fn: Function, isOneTime: boolean}>>();

    on(eventName: string, fn: Function): () => void {
      const eventListeners = this.listeners.get(eventName) || [];
      eventListeners.push({fn, isOneTime: false});
      this.listeners.set(eventName, eventListeners);
      return () => this.off(eventName, fn);
    }

    once(eventName: string, fn: Function): () => void {
      const eventListeners = this.listeners.get(eventName) || [];
      eventListeners.push({fn, isOneTime: true});
      this.listeners.set(eventName, eventListeners);
      return () => this.off(eventName, fn);
    }

    off(eventName: string, fn: Function): void {
      const eventListeners = this.listeners.get(eventName);
      if (!eventListeners) return;
      const index = eventListeners.findIndex(listener => listener.fn === fn);
      if (index !== -1) {
        eventListeners.splice(index, 1);
      }
    }

    emit(eventName: string, ...args: any[]): any[] {
      const eventListeners = this.listeners.get(eventName) || [];
      const results: any[] = [];
      for (const listener of eventListeners) {
        if (listener.isOneTime) {
          const result = listener.fn(...args);
          results.push(result);
          const index = eventListeners.indexOf(listener);
          if (index !== -1) {
            eventListeners.splice(index, 1);
          }
        } else {
          const result = listener.fn(...args);
          results.push(result);
        }
      }
      return results;
    }
  }

  return new EventEmitter();
}
