export function createEventEmitter(): EventEmitter {
  const eventListeners = new Map<string, { regular: Listener[], once: Listener[] }>();

  return {
    on(event: string, listener: Listener): number {
      if (!eventListeners.has(event)) {
        eventListeners.set(event, { regular: [], once: [] });
      }
      const listeners = eventListeners.get(event)!;
      listeners.regular.push(listener);
      return listeners.regular.length;
    },
    once(event: string, listener: Listener): number {
      if (!eventListeners.has(event)) {
        eventListeners.set(event, { regular: [], once: [] });
      }
      const listeners = eventListeners.get(event)!;
      listeners.once.push(listener);
      return listeners.once.length;
    },
    off(event: string, listener: Listener): boolean {
      if (!eventListeners.has(event)) {
        return false;
      }
      const listeners = eventListeners.get(event)!;
      let removed = false;
      const regularIndex = listeners.regular.indexOf(listener);
      if (regularIndex !== -1) {
        listeners.regular.splice(regularIndex, 1);
        removed = true;
      }
      const onceIndex = listeners.once.indexOf(listener);
      if (onceIndex !== -1) {
        listeners.once.splice(onceIndex, 1);
        removed = true;
      }
      return removed;
    },
    emit(event: string, payload: unknown): unknown[] {
      if (!eventListeners.has(event)) {
        return [];
      }
      const listeners = eventListeners.get(event)!;
      const results: unknown[] = [];
      for (const listener of listeners.regular) {
        results.push(listener(payload));
      }
      for (let i = 0; i < listeners.once.length; i++) {
        const listener = listeners.once[i];
        results.push(listener(payload));
        listeners.once.splice(i, 1);
      }
      return results;
    },
    listenerCount(event: string): number {
      if (!eventListeners.has(event)) {
        return 0;
      }
      const listeners = eventListeners.get(event)!;
      return listeners.regular.length + listeners.once.length;
    }
  };
}
