  const states = new Map<string, { requests: number; windowStart: number }>();

  return {
    check(key: string, nowMs: number): boolean {
      const state = states.get(key) || { requests: 0, windowStart: 0 };

      if (nowMs > state.windowStart + 1000) {
        state.windowStart = nowMs;
        state.requests = 1;
      } else {
        if (state.requests < 3) {
          state.requests += 1;
        } else {
          return false;
        }
      }

      states.set(key, state);
      return true;
    },
