export function createEventEmitter() {
  type Listener<T = unknown> = (data?: T) => unknown;
  type OneTimeListener<T = unknown> = (data?: T) => unknown;

  const events: Map<string, { listener: Listener | OneTimeListener; once: boolean }[]> = new Map();

  function on<T = unknown>(eventName: string, listener: Listener<T>) {
    let eventListeners = events.get(eventName);
    if (!eventListeners) {
      eventListeners = [];
      events.set(eventName, eventListeners);
    }
    eventListeners.push({ listener, once: false });
    return () => off(eventName, listener);
  }

  function once<T = unknown>(eventName: string, listener: OneTimeListener<T>) {
    let eventListeners = events.get(eventName);
    if (!eventListeners) {
      eventListeners = [];
      events.set(eventName, eventListeners);
    }
    eventListeners.push({ listener, once: true });
    return () => off(eventName, listener);
  }

  function off(eventName: string, listener: Listener | OneTimeListener) {
    const listeners = events.get(eventName);
    if (!listeners) {
      return false;
    }
    const index = listeners.findIndex((l) => l.listener === listener);
    if (index !== -1) {
      listeners.splice(index, 1);
      return true;
    }
    return false;
  }

  function emit<T = unknown>(eventName: string, data?: T): unknown[] {
    const listeners = events.get(eventName);
    if (!listeners) {
      return [];
    }
    const results: unknown[] = [];

    for (let i = listeners.length - 1; i >= 0; i--) {
      const { listener, once } = listeners[i];
      const result = listener(data);
      results.unshift(result);
      if (once) {
        listeners.splice(i, 1);
      }
    }

    return results;
  }

  return { on, once, off, emit };
}

