/**
 * A factory function that creates a calculator instance with basic arithmetic operations, memory management, and chaining support.
 * 
 * Features:
 * - Basic operations: add, subtract, multiply, divide
 * - Memory management: store, recall, add to memory
 * - Chainable method calls
 * - Independent memory state not affected by value changes
 * 
 * @returns {CalculatorInstance} The calculator instance with all methods.
 */
function createCalculator() {
  // Internal state encapsulated within the closure
  let value = 0;
  let memory = 0;

  /**
   * Adds two numbers.
   * @param a - The first number.
   * @param b - The second number.
   * @returns The sum of a and b.
   */
  function add(a: number, b: number): number {
    return a + b;
  }

  /**
   * Subtracts the second number from the first.
   * @param a - The number to subtract from.
   * @param b - The number to subtract.
   * @returns The difference between a and b.
   */
  function subtract(a: number, b: number): number {
    return a - b;
  }

  /**
   * Multiplies two numbers.
   * @param a - The first number.
   * @param b - The second number.
   * @returns The product of a and b.
   */
  function multiply(a: number, b: number): number {
    return a * b;
  }

  /**
   * Divides the first number by the second.
   * @param a - The numerator.
   * @param b - The denominator.
   * @returns The quotient of a by b, or NaN if b is 0.
   */
  function divide(a: number, b: number): number {
    return b === 0 ? NaN : a / b;
  }

  /**
   * Clears the current value to zero while leaving memory intact.
   * @returns The calculator instance for chaining.
   */
  function clear(): typeof calculator {
    value = 0;
    return calculator;
  }

  /**
   * Retrieves the current value.
   * @returns The current value.
   */
  function result(): number {
    return value;
  }

  /**
   * Stores the current value into memory.
   * @returns The calculator instance for chaining.
   */
  function memoryStore(): typeof calculator {
    memory = value;
    return calculator;
  }

  /**
   * Adds the current value to memory and updates memory but does not change the current value.
   * @returns The calculator instance for chaining.
   */
  function memoryAdd(): typeof calculator {
    memory += value;
    return calculator;
  }

  /**
   * Clears the memory to zero while leaving the current value intact.
   * @returns The calculator instance for chaining.
   */
  function memoryClear(): typeof calculator {
    memory = 0;
    return calculator;
  }

  /**
   * Returns the memory value without altering the current value.
   * @returns The memory value.
   */
  function memoryRecall(): number {
    return memory;
  }

  /**
   * Core interface representing the calculator that can be used with chaining.
   */
  const calculator = {
    add: (a: number, b: number): number => {
      value = add(a, b);
      return value;
    },
    subtract: (a: number, b: number): number => {
      value = subtract(a, b);
      return value;
    },
    multiply: (a: number, b: number): number => {
      value = multiply(a, b);
      return value;
    },
    divide: (a: number, b: number): number => {
      value = divide(a, b);
      return value;
    },
    clear: (): typeof calculator => clear(),
    result,
    memoryStore,
    memoryAdd,
    memoryClear,
    memoryRecall,
  };

  return Object.freeze(calculator);
}

// Export the factory to be imported when imported as an ESM module
export { createCalculator };
