export function createEventEmitter(): EventEmitter {
  const listenersMap = new Map<string, ListenerInfo[]>();

  return {
    on(event: string, listener: Listener) {
      const listeners = listenersMap.get(event) || [];
      listeners.push({ listener, isOnce: false });
      listenersMap.set(event, listeners);
      return listeners.length;
    },

    once(event: string, listener: Listener) {
      const listeners = listenersMap.get(event) || [];
      listeners.push({ listener, isOnce: true });
      listenersMap.set(event, listeners);
      return listeners.length;
    },

    off(event: string, listener: Listener) {
      const listeners = listenersMap.get(event) || [];
      const filtered = listeners.filter(l => l.listener !== listener);
      if (filtered.length === 0) {
        listenersMap.delete(event);
      } else {
        listenersMap.set(event, filtered);
      }
      return filtered.length !== listeners.length;
    },

    emit(event: string, payload: unknown) {
      const listeners = listenersMap.get(event) || [];
      const results: unknown[] = [];
      for (const { listener, isOnce } of listeners) {
        results.push(listener(payload));
        if (isOnce) {
          const index = listeners.indexOf({ listener, isOnce });
          if (index !== -1) listeners.splice(index, 1);
          if (listeners.length === 0) listenersMap.delete(event);
        }
      }
      return results;
    },

    listenerCount(event: string) {
      return (listenersMap.get(event) || []).length;
    },
  };
}

type Listener = (payload: unknown) => unknown;

interface EventEmitter {
  on(event: string, listener: Listener): number;
  once(event: string, listener: Listener): number;
  off(event: string, listener: Listener): boolean;
  emit(event: string, payload: unknown): unknown[];
  listenerCount(event: string): number;
}
