// event-system.ts
export const createEventEmitter = () => {
  const listeners = {
    normal: new Map<string, { callback: () => any; once: boolean }>(),
    oneTime: new Map<string, { callback: () => any; once: boolean }>()
  };

  function add(name: string, callback: () => any, once?: boolean) {
    if (listeners.normal.has(name)) {
      listeners.normal.get(name)!.callback = callback;
      listeners.normal.get(name)!.once = once || false;
    } else {
      listeners.normal.set(name, { callback, once });
    }
  }

  function remove(name: string, once?: boolean) {
    if (listeners.normal.has(name)) {
      listeners.normal.delete(name);
    }
    if (listeners.oneTime.has(name)) {
      listeners.oneTime.delete(name);
    }
  }

  function emit(name: string, ...args: any[]) {
    const callbacks = [];
    const listeners = [listeners.normal, listeners.oneTime];

    for (const listener of listeners) {
      if (listener.has(name)) {
        const listenerData = listener.get(name)!;
        callbacks.push(listenerData.callback(...args));
        if (listenerData.once) {
          listener.delete(name);
        }
      }
    }
    return callbacks;
  }

  return { add, remove, emit };
};
