export const createRateLimiter = (nowMs: number) => {
  const keys = new Map<string, { last: number; count: number }>();

  return {
    increment(key: string) {
      if (!keys.has(key)) {
        keys.set(key, { last: nowMs, count: 0 });
      }
      const { last, count } = keys.get(key)!;
      const now = nowMs;
      if (now - last < 1000) {
        return count + 1;
      }
      keys.set(key, { last: now, count: 0 });
      return count + 1;
    },
    isAllowed(key: string) {
      if (!keys.has(key)) return false;
      const { last, count } = keys.get(key)!;
      if (nowMs - last < 1000) {
        return count < 3;
      }
      return count < 3;
    },
    reset(key: string) {
      if (!keys.has(key)) return;
      keys.set(key, { last: nowMs, count: 0 });
    }
  };
};
