export function createRateLimiter(): RateLimiter {
  const states = new Map<string, { count: number; windowStart: number }>();

  return {
    allow(key: string, nowMs: number): boolean {
      if (!states.has(key)) {
        states.set(key, { count: 0, windowStart: nowMs });
      }

      const { count, windowStart } = states.get(key)!;
      const remaining = Math.min(count, 3);

      if (nowMs - windowStart >= 1000) {
        states.set(key, { count: 0, windowStart: nowMs });
      }

      return count < 3 && count + remaining > 0;
    },

    remaining(key: string, nowMs: number): number {
      if (!states.has(key)) return 0;

      const { count, windowStart } = states.get(key)!;
      const windowDuration = 1000;

      if (nowMs - windowStart >= windowDuration) {
        return 0;
      }

      return count - Math.min(count, 3);
    },

    reset(key: string) {
      if (!states.has(key)) return;

      states.set(key, { count: 0, windowStart: Date.now() });
    }
  };
}

interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}
