export function createTtlCache(): TtlCache {
  const cache: Record<string, { expiresAt: number; value: unknown }> = {};

  const nowMs = () => Date.now();

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number) {
      if (ttlMs === 0) {
        cache[key] = { expiresAt: nowMs, value };
      } else {
        cache[key] = { expiresAt: nowMs + ttlMs, value };
      }
      // Refresh expiration on update
      if (cache[key]) {
        cache[key].expiresAt = nowMs + (ttlMs || 1000);
      }
    },
    get(key: string, nowMs: number) {
      if (cache[key] && cache[key].expiresAt > nowMs) {
        return cache[key].value;
      }
      return undefined;
    },
    has(key: string, nowMs: number) {
      return cache[key] && cache[key].expiresAt > nowMs;
    },
    delete(key: string) {
      const exists = cache[key];
      if (!exists) return false;
      delete cache[key];
      return true;
    },
    size(nowMs: number) {
      let count = 0;
      for (const entry of Object.values(cache)) {
        if (entry.expiresAt > nowMs) count++;
      }
      return count;
    },
    clear() {
      cache.length = 0;
    }
  };
}

interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
}
