class EventEmitterInternal {
  private events: Record<string, Listener[]> = {};

  on(event: string, listener: Listener): number {
    const listeners = this.events[event] || [];
    this.events[event] = [...listeners, listener];
    return this.listenerCount(event);
  }

  once(event: string, listener: Listener): number {
    const listenerForEvent = (payload: unknown) => {
      this.off(event, listener);
      listener(payload);
    };
    return this.on(event, listenerForEvent);
  }

  off(event: string, listener: Listener): boolean {
    const listeners = this.events[event];
    if (!listeners) return false;
    const index = listeners.indexOf(listener);
    if (index === -1) return false;
    listeners.splice(index, 1);
    return true;
  }

  emit(event: string, payload: unknown): unknown[] {
    if (!this.events[event]) return [];
    const listeners = this.events[event];
    const result: unknown[] = [];
    listeners.forEach(listener => {
      const res = listener(payload);
      result.push(res || undefined);
    });
    return result;
  }

  listenerCount(event: string): number {
    return this.events[event]?.length || 0;
  }
}

export function createEventEmitter(): EventEmitter {
  const internal = new EventEmitterInternal();
  return {
    on: internal.on.bind(internal),
    once: internal.once.bind(internal),
    off: internal.off.bind(internal),
    emit: internal.emit.bind(internal),
    listenerCount: internal.listenerCount.bind(internal),
  };
}
