interface Listener<T> {
  (value: T): any;
}

interface EventEmitter<T> {
  on(name: string, listener: Listener<T>): void;
  off(name: string, listener: Listener<T>): void;
  emit<T>(name: string, ...args: any[]): any[];
}

function createEventEmitter<T>(): EventEmitter<T> {
  const events: { [key: string]: Listener<T>[] } = {};
  const emitHistory: any[] = [];

  const emit = (name: string, ...args: any[]) => {
    const listeners = events[name] || [];
    const result = listeners.map((listener) => listener(args));
    emitHistory.push(result, name, args);
    return result;
  };

  const on = (
    name: string,
    listener: Listener<T>,
  ): void => {
    events[name] = (events[name] || []).concat(listener);
  };

  const off = (name: string, listener: Listener<T>) => {
    if (events[name]) {
      events[name] = events[name].filter((l) => l !== listener);
    }
  };

  return { on, off, emit };
}

export { createEventEmitter };
