type Listener = (payload: unknown) => unknown;

interface EventEmitter {
  on(event: string, listener: Listener): number;
  once(event: string, listener: Listener): number;
  off(event: string, listener: Listener): boolean;
  emit(event: string, payload: unknown): unknown[];
  listenerCount(event: string): number;
}

class EventEmitter {
  private listeners = new Map<string, Array<Listener>>();

  on(event: string, listener: Listener): number {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, []);
    }
    this.listeners.get(event)!.push(listener);
    return this.listeners.get(event)!.length;
  }

  once(event: string, listener: Listener): number {
    const wrappedListener = (payload: unknown) => {
      listener(payload);
      const index = this.listeners.get(event)!.indexOf(wrappedListener);
      if (index !== -1) {
        this.listeners.get(event)!.splice(index, 1);
      }
    };
    if (!this.listeners.has(event)) {
      this.listeners.set(event, []);
    }
    this.listeners.get(event)!.push(wrappedListener);
    return this.listeners.get(event)!.length;
  }

  off(event: string, listener: Listener): boolean {
    const eventListeners = this.listeners.get(event);
    if (eventListeners) {
      const index = eventListeners.indexOf(listener);
      if (index !== -1) {
        eventListeners.splice(index, 1);
        return true;
      }
    }
    return false;
  }

  emit(event: string, payload: unknown): unknown[] {
    const eventListeners = this.listeners.get(event) || [];
    return eventListeners.map(listener => listener(payload));
