export function createRateLimiter() {
  const cache = new Map<string, { timestamp: number; count: number }>();

  return {
    limit: (key: string, nowMs: number) => {
      const state = cache.get(key);
      if (state) {
        const elapsed = nowMs - state.timestamp;
        if (elapsed >= 1000) {
          cache.set(key, { timestamp: nowMs, count: 1 });
          return true;
        }
        state.count++;
        if (state.count <= 3) {
          cache.set(key, state);
          return true;
        }
        return false;
      } else {
        cache.set(key, { timestamp: nowMs, count: 1 });
        return true;
      }
    },
    reset: (key: string) => {
      cache.delete(key);
    }
  };
}

