export function createRateLimiter(): RateLimiter {
  return {
    allow: (key, nowMs) => {
      const state = rateLimiterMap.get(key);
      if (!state) {
        rateLimiterMap.set(key, { windowStart: nowMs, count: 0 });
        return true;
      }
      const expired = nowMs - state.windowStart >= 1000;
      if (expired) {
        rateLimiterMap.set(key, { windowStart: nowMs, count: 0 });
      }
      const newCount = state.count + 1;
      if (newCount > 3) return false;
      rateLimiterMap.set(key, { windowStart: state.windowStart, count: newCount });
      return true;
    },
    remaining: (key, nowMs) => {
      const state = rateLimiterMap.get(key);
      if (!state) return 3;
      const expired = nowMs - state.windowStart >= 1000;
      if (expired) {
        rateLimiterMap.set(key, { windowStart: nowMs, count: 0 });
      }
      return 3 - (rateLimiterMap.get(key)?.count ?? 0);
    },
    reset: (key) => {
      rateLimiterMap.delete(key);
    }
  };
}
