export function createEventEmitter(): EventEmitter {
  type Listener = (payload: unknown) => unknown;
  type Registration = {
    listener: Listener;
    once: boolean;
  };

  const listeners: Record<string, Registration[]> = {};

  return {
    on(event: string, listener: Listener): number {
      if (!listeners[event]) {
        listeners[event] = [];
      }
      listeners[event].push({ listener, once: false });
      return listeners[event].length;
    },

    once(event: string, listener: Listener): number {
      if (!listeners[event]) {
        listeners[event] = [];
      }
      listeners[event].push({ listener, once: true });
      return listeners[event].length;
    },

    off(event: string, listener: Listener): boolean {
      const registrations = listeners[event];
      if (!registrations) return false;

      for (let i = 0; i < registrations.length; i++) {
        if (registrations[i].listener === listener) {
          registrations.splice(i, 1);
          return true;
        }
      }
      return false;
    },

    emit(event: string, payload: unknown): unknown[] {
      const registrations = listeners[event] || [];
      const results: unknown[] = [];

      for (let i = 0; i < registrations.length; i++) {
        const reg = registrations[i];
        results.push(reg.listener(payload));
        if (reg.once) {
          registrations.splice(i, 1);
          i--;
        }
      }

      return results;
    },

    listenerCount(event: string): number {
      return listeners[event] ? listeners[event].length : 0;
    },
  };
}
