export function createEventEmitter() {
  type Listener = (...args: any[]) => any;
  const map: Record<string, { listeners: {fn: Listener, oneTime: boolean}[] }> = {};

  function add(event: string, fn: Listener, oneTime: boolean) {
    if (!map[event]) map[event] = { listeners: [] };
    map[event].listeners.push({fn, oneTime});
  }

  function on(event: string, fn: Listener, oneTime = false) {
    add(event, fn, oneTime);
  }

  function off(event: string, fn: Listener) {
    const arr = map[event];
    if (!arr) return;
    for (let i = 0; i < arr.listeners.length; i++) {
      if (arr.listeners[i].fn === fn) {
        arr.listeners.splice(i, 1);
        return;
      }
    }
  }

  function emit(event: string, ...args: any[]): any[] {
    const arr = map[event];
    if (!arr) return [];
    const results: any[] = [];
    const copy = arr.listeners.slice();
    for (const {fn, oneTime} of copy) {
      const ret = fn(...args);
      results.push(ret);
      if (oneTime) {
        off(event, fn);
      }
    }
    return results;
  }

  return { on, off, emit };
}
