type Listener = (payload: unknown) => unknown;

interface EventEmitter {
  on(event: string, listener: Listener): number;
  once(event: string, listener: Listener): number;
  off(event: string, listener: Listener): boolean;
  emit(event: string, payload: unknown): unknown[];
  listenerCount(event: string): number;
}

function createEventEmitter(): EventEmitter {
  const listeners: Record<string, Array<{fn: Listener; once: boolean}>> = {};

  function add(event: string, fn: Listener, once: boolean): number {
    const arr = listeners[event] || (listeners[event] = []);
    arr.push({fn, once});
    return arr.length;
  }

  return {
    on(event, listener) {
      return add(event, listener, false);
    },
    once(event, listener) {
      const wrapper = (payload: unknown) => {
        const result = listener(payload);
        const arr = listeners[event];
        if (arr) {
          const idx = arr.findIndex(e => e.fn === wrapper);
          if (idx !== -1) arr.splice(idx, 1);
        }
        return result;
      };
      return add(event, wrapper, true);
    },
    off(event, listener) {
      const arr = listeners[event];
      if (!arr) return false;
      for (let i = 0; i < arr.length; i++) {
        if (arr[i].fn === listener) {
          arr.splice(i, 1);
          return true;
        }
      }
      return false;
    },
    emit(event, payload) {
      const arr = listeners[event];
      if (!arr) return [];
      const result: unknown[] = [];
      const copy = [...arr];
      for (const entry of copy) {
        const r = entry.fn(payload);
        result.push(r);
        if (entry.once) {
          const idx = arr.indexOf(entry);
          if (idx !== -1) arr.splice(idx, 1);
        }
      }
      return result;
    },
    listenerCount(event) {
      return listeners[event]?.length ?? 0;
    },
  };
}

export { createEventEmitter };

export function createRateLimiter() {
  const store = new Map<string, number[]>();
  return {
    allow(key: string, nowMs: number): boolean {
      const timestamps = store.get(key) ?? [];
      const windowStart = nowMs - 1000;
      const recent = timestamps.filter(t => t >= windowStart);
      if (recent.length < 3) {
        recent.push(nowMs);
        store.set(key, recent);
        return true;
      }
      return false;
    },
    reset(key: string): void {
      const arr = store.get(key);
      if (arr) {
        arr.length = 0;
        store.set(key, arr);
      }
    }
  };
}

export function createRateLimiter() {
  const limit = 3;
  const windowMs = 1000;
  const store = new Map<string, number[]>();

  function allow(key: string, nowMs: number): boolean {
    const timestamps = store.get(key) ?? [];
    const cutoff = nowMs - windowMs;
    const recent = timestamps.filter(t => t > cutoff);
    if (recent.length < limit) {
      recent.push(nowMs);
      store.set(key, recent);
      return true;
    }
    return false;
  }

  function remaining(key: string, nowMs: number): number {
    const timestamps = store.get(key) ?? [];
    const cutoff = nowMs - windowMs;
    const recent = timestamps.filter(t => t > cutoff);
    return Math.max(0, limit - recent.length);
  }

  function reset(key: string): void {
    store.delete(key);
  }

  return { allow, remaining, reset };
}

