type Listener<T = any> = (payload: T) => void | Promise<void>;
type Emitter = {
  on<K extends string>(event: K, listener: Listener): void;
  once<K extends string>(event: K, listener: Listener): void;
  off<K extends string>(event: K, listener?: Listener): void;
  emit<K extends string>(event: K, payload?: unknown): ReturnType<Listener>[];
