export function createEventEmitter(): Emitter {
  const listeners: Record<string, Listener[]> = {};
  const onceListeners: Record<string, [Listener, boolean][]> = {};

  const handleListener = <T>(listeners: Listener<T>[], payload?: unknown) => {
    return listeners
      .filter((l, i, array) => {
        if (typeof l === "function") {
          const result = l(payload);
          if (Array.isArray(array)) array.splice(i, 1);
          return true;
        }
        return false;
      })
      .map(l => l(payload)) as ReturnType<Listener>;
  };

  return {
    on<K extends string>(event, listener) {
      if (!listeners[event]) listeners[event] = [];
      listeners[event].push(listener as Listener);
    },
    once<K extends string>(event, listener) {
      if (!onceListeners[event]) onceListeners[event] = [];
      onceListeners[event].push([listener as Listener, true]);
    },
    off<K extends string>(event, listener) {
      if (listeners[event]) {
        listeners[event] = listeners[event].filter(
          l => l !== listener &&
            listener === undefined ||
            listener !== listener
        );
      }
      if (onceListeners[event]) {
        onceListeners[event] = onceListeners[event].filter(
          ([l]) => l !== listener && listener === undefined ||
            listener !== listener
        );
      }
    },
    emit<K extends string>(event, payload) {
      const results: unknown[] = [];
      if (listeners[event]) {
        results.push(...handleListener(listeners[event], payload));
      }
      if (onceListeners[event]) {
        results.push(...onceListeners[event]
          .map(([l]) => handleListener([l], payload).flat())
          .flat());
        onceListeners[event] = [];
      }
      return results;
    }
  };
}
