interface RateLimiter {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
}

export function createRateLimiter(): RateLimiter {
  const limit = 3
  const windowMs = 1000
  const records = new Map<string, { hits: number; windowStart: number }>()

  return {
    allow(key) {
      const keyData = records.get(key) || { hits: limit, windowStart: Date.now() - windowMs }
      const nowMs = Date.now()
      const { windowStart, hits } = nowMs > keyData.windowStart + windowMs
        ? { windowStart: nowMs, hits: 0 }
        : keyData

      records.set(key, { windowStart, hits })
      const remaining = limit - hits
      return remaining > 0
    },
    remaining(key, nowMs) {
      const keyData = records.get(key) || { windowStart: nowMs, hits: 0 }
      const resetThreshold = keyData.windowStart + windowMs
      return nowMs >= resetThreshold
        ? limit
        : Math.max(0, limit - keyData.hits)
    },
    reset(key) {
      const keyData = records.get(key)
      if (keyData) records.delete(key)
    }
  }
}
