export function createTtlCache(): TtlCache {
    const entries = new Map<string, { expiresAt: number; value: unknown }>();
    const defaultTTL = 1000;

    return {
        set(key: string, value: unknown, nowMs: number, ttlMs = defaultTTL): void {
            entries.set(key, { expiresAt: ttlMs === 0 ? nowMs : nowMs + ttlMs, value });
        },
        get(key: string, nowMs: number): unknown {
            const entry = entries.get(key);
            if (!entry || entry.expiresAt <= nowMs) return undefined;
            return entry.value;
        },
        has(key: string, nowMs: number): boolean {
            const entry = entries.get(key);
            return entry !== undefined && entry.expiresAt > nowMs;
        },
        delete(key: string): boolean {
            return entries.delete(key);
        },
        size(nowMs: number): number {
            return [...entries.entries()]
                .filter(([_, { expiresAt }]) => expiresAt > nowMs)
                .length;
        },
        clear(): void {
            entries.clear();
        }
    };
}

interface TtlCache {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
    get(key: string, nowMs: number): unknown
    has(key: string, nowMs: number): boolean
    delete(key: string): boolean
    size(nowMs: number): number
    clear(): void
}
