export function createEventEmitter(): EventEmitter {
  const listeners: { [event: string]: Listener[] } = {};

  const on: EventEmitter['on'] = (event, listener) => {
    if (!listeners[event]) {
      listeners[event] = [];
    }
    listeners[event].push(listener);
    return listeners[event].length;
  };

  const once: EventEmitter['once'] = (event, listener) => {
    const onceListener = (payload: unknown) => {
      listener(payload);
      off(event, onceListener);
    };
    return on(event, onceListener);
  };

  const off: EventEmitter['off'] = (event, listener) => {
    if (listeners[event]) {
      const index = listeners[event].indexOf(listener);
      if (index > -1) {
        listeners[event].splice(index, 1);
        return true;
      }
    }
    return false;
  };

  const emit: EventEmitter['emit'] = (event, payload) => {
    if (listeners[event]) {
      return listeners[event].map(listener => listener(payload));
    }
    return [];
  };

  const listenerCount: EventEmitter['listenerCount'] = (event) => {
    return listeners[event]?.length || 0;
  };

  return { on, once, off, emit, listenerCount };
}
