export function createRateLimiter(): {
  tryRequest(key: string, nowMs: number): boolean;
  reset(key: string): void;
} {
  const buckets = new Map<string, { count: number; resetsAt: number }>();

  function tryRequest(key: string, nowMs: number): boolean {
    if (!buckets.has(key)) {
      buckets.set(key, { count: 1, resetsAt: nowMs + 1000 });
      return true;
    }

    const bucket = buckets.get(key)!;
    if (nowMs >= bucket.resetsAt) {
      bucket.count = 1;
      bucket.resetsAt = nowMs + 1000;
      return true;
    }

    if (bucket.count < 3) {
      bucket.count++;
      return true;
    }

    return false;
  }

  function reset(key: string) {
    buckets.delete(key);
  }

  return { tryRequest, reset };
}
