export function createRateLimiter(): RateLimiter {
  const limits = new Map<string, { count: number; windowStart: number }>();

  return {
    allow(key: string, nowMs: number): boolean {
      let limitEntry = limits.get(key);
      if (!limitEntry || nowMs - limitEntry.windowStart >= 1000) {
        limitEntry = { count: 1, windowStart: nowMs };
        limits.set(key, limitEntry);
        return true;
      }

      if (limitEntry.count < 3) {
        limitEntry.count++;
        return true;
      }

      return false;
    },

    remaining(key: string, nowMs: number): number {
      const limitEntry = limits.get(key);
      if (!limitEntry || nowMs - limitEntry.windowStart >= 1000) {
        return 3;
      }

      return 3 - limitEntry.count;
    },

    reset(key: string): void {
      limits.delete(key);
    },
  };
}
