const getDefaultTtlMs = (ttlMs?: number) => ttlMs ?? 1000;

export function createTtlCache(): TtlCache {
  const cache = new Map<string, { value: unknown; expiresAt: number }>();

  return {
    set: (key: string, value: unknown, nowMs: number, ttlMs?: number) => {
      const ttl = getDefaultTtlMs(ttlMs);
      const expiresAt = nowMs + ttl;
      cache.set(key, { value, expiresAt });
    },
    get: (key: string, nowMs: number) => {
      const entry = cache.get(key);
      if (entry && entry.expiresAt > nowMs) {
        return entry.value;
      }
      return undefined;
    },
    has: (key: string, nowMs: number) => {
      const entry = cache.get(key);
      if (entry && entry.expiresAt > nowMs) {
        return true;
      }
      return false;
    },
    delete: (key: string): boolean => {
      return cache.delete(key);
    },
    size: (nowMs: number): number => {
      let count = 0;
      for (const [_, entry] of cache) {
        if (entry.expiresAt > nowMs) {
          count++;
        }
      }
      return count;
    },
    clear: () => {
      cache.clear();
    }
  };
}
